import ExcelJS from "exceljs";

/**
 * BreathMap's current browser upload profile, based on the supplied acquisition
 * workbook. These 50 MiB file / 256 MiB declared ZIP-output limits are browser
 * resource limits, not scientific acceptance criteria or sensor specifications.
 * ZIP checks inspect declarations before ExcelJS loads the workbook; they are
 * not a streaming decompression memory guarantee for adversarial archives.
 * No signals are modified, joined by row, classified or sent to a model here.
 */
export const RECORDING_XLSX_SCHEMA_VERSION = "breathmap-acquisition-xlsx-v1";
export const RECORDING_XLSX_BROWSER_LIMITS = {
  fileBytes: 50 * 1024 * 1024,
  declaredUncompressedBytes: 256 * 1024 * 1024,
} as const;

export interface RecordingFileSummary {
  schemaVersion: string;
  sheets: Array<{ name: string; rows: number }>;
}

export class RecordingFileValidationError extends Error {
  readonly code: string;
  readonly en: string;
  readonly zh: string;

  constructor(code: string, en: string, zh: string) {
    super(en);
    this.name = "RecordingFileValidationError";
    this.code = code;
    this.en = en;
    this.zh = zh;
  }
}

const INPUT_SHEETS = [
  {
    name: "磁场数据",
    headers: ["点数", "PC接收时间", "工作时间_秒", "磁场响应信号_mT", "信号模式", "TMR_X_mT", "TMR_Y_mT", "TMR_Z_mT", "ESP32_TIMESTAMP_US", "TMR_QUEUE_DROPS"],
    deviceTimeColumn: 9,
    signalModeColumn: 5,
  },
  {
    name: "SIG差分电压",
    headers: ["点数", "PC接收时间", "工作时间_秒", "ESP32_TIME_US", "SIG_INPUT_uV"],
    deviceTimeColumn: 4,
    signalModeColumn: 0,
  },
] as const;

function rejectRecording(code: string, en: string, zh: string): never {
  throw new RecordingFileValidationError(code, en, zh);
}

function checkZipPackage(buffer: ArrayBuffer): void {
  const view = new DataView(buffer);
  const bytes = new Uint8Array(buffer);
  const invalidZip = (): never => rejectRecording("INVALID_XLSX_ZIP", "The file is not a supported, intact XLSX ZIP package.", "文件不是受支持的完整 XLSX ZIP 包。");
  const encrypted = (): never => rejectRecording("ENCRYPTED_XLSX", "Encrypted workbooks are not supported. Upload an unencrypted XLSX file.", "暂不支持加密工作簿，请上传未加密的 XLSX 文件。");
  const zip64 = (): never => rejectRecording("ZIP64_NOT_SUPPORTED", "ZIP64 workbooks are not supported by this browser uploader.", "当前浏览器上传器不支持 ZIP64 工作簿。");
  const bounds = (start: number, length: number, end = bytes.length): void => {
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(length) || start < 0 || length < 0 || start + length > end) invalidZip();
  };
  const checkExtras = (start: number, length: number): void => {
    const end = start + length;
    bounds(start, length);
    while (start < end) {
      bounds(start, 4, end);
      const kind = view.getUint16(start, true);
      const size = view.getUint16(start + 2, true);
      bounds(start + 4, size, end);
      if (kind === 0x0001) zip64();
      start += 4 + size;
    }
  };

  if (bytes.length < 22) invalidZip();
  // Password-protected Office files may be OLE containers rather than ZIP files.
  if (view.getUint32(0, true) === 0xe011cfd0) encrypted();
  if (view.getUint32(0, true) !== 0x04034b50) invalidZip();

  let endRecord = -1;
  const earliestEnd = Math.max(0, bytes.length - 22 - 0xffff);
  for (let offset = bytes.length - 22; offset >= earliestEnd; offset--) {
    if (view.getUint32(offset, true) === 0x06054b50 && offset + 22 + view.getUint16(offset + 20, true) === bytes.length) {
      endRecord = offset;
      break;
    }
  }
  if (endRecord < 0) invalidZip();
  if (endRecord >= 20 && view.getUint32(endRecord - 20, true) === 0x07064b50) zip64();
  const disk = view.getUint16(endRecord + 4, true);
  const directoryDisk = view.getUint16(endRecord + 6, true);
  const diskEntries = view.getUint16(endRecord + 8, true);
  const totalEntries = view.getUint16(endRecord + 10, true);
  const directorySize = view.getUint32(endRecord + 12, true);
  const directoryStart = view.getUint32(endRecord + 16, true);
  if (totalEntries === 0xffff || diskEntries === 0xffff || directorySize === 0xffffffff || directoryStart === 0xffffffff) zip64();
  if (disk !== 0 || directoryDisk !== 0 || diskEntries !== totalEntries) rejectRecording("MULTIPART_ZIP_NOT_SUPPORTED", "Split ZIP workbooks are not supported.", "暂不支持分卷 ZIP 工作簿。");
  if (totalEntries === 0 || directoryStart + directorySize !== endRecord) invalidZip();
  bounds(directoryStart, directorySize, endRecord);

  let offset = directoryStart;
  let declaredBytes = 0;
  const names = new Set<string>();
  const ranges: Array<{ start: number; end: number }> = [];
  const decoder = new TextDecoder("utf-8", { fatal: true });
  for (let entry = 0; entry < totalEntries; entry++) {
    bounds(offset, 46, endRecord);
    if (view.getUint32(offset, true) !== 0x02014b50) invalidZip();
    const flags = view.getUint16(offset + 8, true);
    const method = view.getUint16(offset + 10, true);
    const compressedSize = view.getUint32(offset + 20, true);
    const uncompressedSize = view.getUint32(offset + 24, true);
    const nameSize = view.getUint16(offset + 28, true);
    const extraSize = view.getUint16(offset + 30, true);
    const commentSize = view.getUint16(offset + 32, true);
    const startDisk = view.getUint16(offset + 34, true);
    const localStart = view.getUint32(offset + 42, true);
    if ((flags & 0x2041) !== 0) encrypted();
    if (compressedSize === 0xffffffff || uncompressedSize === 0xffffffff || localStart === 0xffffffff || startDisk === 0xffff) zip64();
    if (startDisk !== 0) rejectRecording("MULTIPART_ZIP_NOT_SUPPORTED", "Split ZIP workbooks are not supported.", "暂不支持分卷 ZIP 工作簿。");
    if (method !== 0 && method !== 8) rejectRecording("ZIP_COMPRESSION_NOT_SUPPORTED", "This XLSX compression method is not supported.", "暂不支持此 XLSX 文件的压缩方式。");
    bounds(offset + 46, nameSize + extraSize + commentSize, endRecord);
    let name: string;
    try { name = decoder.decode(bytes.subarray(offset + 46, offset + 46 + nameSize)); }
    catch { return invalidZip(); }
    if (!name || name.includes("\0") || name.includes("\\") || name.startsWith("/") || name.split("/").some(part => part === ".." || part === ".") || names.has(name)) invalidZip();
    names.add(name);
    checkExtras(offset + 46 + nameSize, extraSize);
    declaredBytes += uncompressedSize;
    if (declaredBytes > RECORDING_XLSX_BROWSER_LIMITS.declaredUncompressedBytes) rejectRecording("XLSX_UNCOMPRESSED_LIMIT", "The workbook exceeds the current browser limit of 256 MiB of declared ZIP output.", "工作簿超过当前浏览器限制：ZIP 声明解压总量不得大于 256 MiB。");

    bounds(localStart, 30, directoryStart);
    if (view.getUint32(localStart, true) !== 0x04034b50) invalidZip();
    const localFlags = view.getUint16(localStart + 6, true);
    const localMethod = view.getUint16(localStart + 8, true);
    const localNameSize = view.getUint16(localStart + 26, true);
    const localExtraSize = view.getUint16(localStart + 28, true);
    if ((localFlags & 0x2041) !== 0) encrypted();
    if (localFlags !== flags || localMethod !== method || localNameSize !== nameSize) invalidZip();
    bounds(localStart + 30, localNameSize + localExtraSize + compressedSize, directoryStart);
    for (let index = 0; index < nameSize; index++) {
      if (bytes[localStart + 30 + index] !== bytes[offset + 46 + index]) invalidZip();
    }
    checkExtras(localStart + 30 + localNameSize, localExtraSize);
    const dataStart = localStart + 30 + localNameSize + localExtraSize;
    ranges.push({ start: localStart, end: dataStart + compressedSize });
    if ((flags & 0x0008) === 0 && (view.getUint32(localStart + 18, true) !== compressedSize || view.getUint32(localStart + 22, true) !== uncompressedSize)) invalidZip();
    offset += 46 + nameSize + extraSize + commentSize;
  }
  if (offset !== directoryStart + directorySize) invalidZip();
  ranges.sort((left, right) => left.start - right.start);
  for (let index = 1; index < ranges.length; index++) {
    if (ranges[index].start < ranges[index - 1].end) invalidZip();
  }
  if (!["[Content_Types].xml", "_rels/.rels", "xl/workbook.xml"].every(name => names.has(name))) rejectRecording("NOT_XLSX_WORKBOOK", "The ZIP file does not contain a standard XLSX workbook.", "该 ZIP 文件不包含标准 XLSX 工作簿。");
}

function validPcTime(value: unknown): boolean {
  if (typeof value !== "string") return false;
  const match = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})\.(\d{3})$/.exec(value);
  if (!match) return false;
  const [, yearText, monthText, dayText, hourText, minuteText, secondText] = match;
  const year = Number(yearText), month = Number(monthText), day = Number(dayText);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= days[month - 1] && Number(hourText) <= 23 && Number(minuteText) <= 59 && Number(secondText) <= 59;
}

function hasValue(value: unknown): boolean {
  return value !== null && value !== undefined && value !== "";
}

function checkCell(cell: ExcelJS.Cell, sheet: string): void {
  const value = cell.value;
  if (cell.isMerged) rejectRecording("MERGED_DATA_CELL", `Unmerge ${sheet}!${cell.address} before uploading.`, `请先取消合并 ${sheet}!${cell.address}，再上传。`);
  if (cell.type === ExcelJS.ValueType.Formula || (value !== null && typeof value === "object" && ("formula" in value || "sharedFormula" in value))) rejectRecording("FORMULA_NOT_ALLOWED", `Formulas are not accepted at ${sheet}!${cell.address}. Use recorded values.`, `${sheet}!${cell.address} 不接受公式，请使用采集值。`);
}

/** Validate one file, returning counts only. Different channel lengths are valid. */
export async function validateRecordingFile(file: File): Promise<RecordingFileSummary> {
  if (!file || typeof file.name !== "string" || !/\.xlsx$/i.test(file.name)) rejectRecording("XLSX_REQUIRED", "Choose an XLSX acquisition workbook.", "请选择 XLSX 格式的采集工作簿。");
  if (!Number.isFinite(file.size) || file.size <= 0) rejectRecording("EMPTY_XLSX", "The XLSX file is empty.", "XLSX 文件为空。");
  if (file.size > RECORDING_XLSX_BROWSER_LIMITS.fileBytes) rejectRecording("XLSX_FILE_LIMIT", "The file exceeds the current browser upload limit of 50 MiB.", "文件超过当前浏览器上传限制：50 MiB。");
  let buffer: ArrayBuffer;
  try { buffer = await file.arrayBuffer(); }
  catch { return rejectRecording("FILE_READ_FAILED", "The file could not be read. Choose it again and retry.", "无法读取文件，请重新选择后重试。"); }
  if (buffer.byteLength !== file.size) rejectRecording("FILE_READ_FAILED", "The file could not be read completely. Choose it again and retry.", "文件未能完整读取，请重新选择后重试。");
  checkZipPackage(buffer);

  const workbook = new ExcelJS.Workbook();
  try { await workbook.xlsx.load(buffer); }
  catch { return rejectRecording("XLSX_READ_FAILED", "The XLSX workbook could not be opened. Check that it is intact and unencrypted.", "无法打开 XLSX 工作簿，请检查文件是否完整且未加密。"); }
  if (workbook.worksheets.length !== INPUT_SHEETS.length || INPUT_SHEETS.some(spec => !workbook.getWorksheet(spec.name))) rejectRecording("WORKSHEET_MISMATCH", "The workbook must contain exactly the two sheets 磁场数据 and SIG差分电压.", "工作簿必须且只能包含「磁场数据」与「SIG差分电压」两个工作表。");

  const summary: RecordingFileSummary = { schemaVersion: RECORDING_XLSX_SCHEMA_VERSION, sheets: [] };
  for (const spec of INPUT_SHEETS) {
    const sheet = workbook.getWorksheet(spec.name)!;
    const header = sheet.getRow(1);
    for (let column = 1; column <= spec.headers.length; column++) {
      const cell = header.getCell(column);
      checkCell(cell, spec.name);
      if (cell.value !== spec.headers[column - 1]) rejectRecording("HEADER_MISMATCH", `The header at ${spec.name}!${cell.address} must be ${spec.headers[column - 1]}. Keep the standard column order.`, `${spec.name}!${cell.address} 的表头必须为「${spec.headers[column - 1]}」，请保留标准列顺序。`);
    }
    header.eachCell((cell, column) => {
      if (column > spec.headers.length && hasValue(cell.value)) rejectRecording("EXTRA_COLUMN", `Unexpected column in sheet ${spec.name}.`, `工作表「${spec.name}」含有标准格式以外的列。`);
    });

    let count = 0;
    let previousRow = 1;
    let previousPoint: number | undefined;
    let previousDeviceTime: number | undefined;
    // eachRow skips empty trailing rows. Gaps between actual rows are rejected.
    sheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return;
      if (!row.values || !row.hasValues) return;
      if (rowNumber !== previousRow + 1) rejectRecording("EMPTY_DATA_ROW", `Sheet ${spec.name} contains an empty row inside its data.`, `工作表「${spec.name}」的数据中间含有空行。`);
      row.eachCell((cell, column) => {
        if (column > spec.headers.length && hasValue(cell.value)) rejectRecording("EXTRA_COLUMN", `Unexpected column in sheet ${spec.name}.`, `工作表「${spec.name}」含有标准格式以外的列。`);
      });
      for (let column = 1; column <= spec.headers.length; column++) {
        const cell = row.getCell(column);
        checkCell(cell, spec.name);
        const value = cell.value;
        if (!hasValue(value)) rejectRecording("EMPTY_DATA_CELL", `A required value is missing at ${spec.name}!${cell.address}.`, `${spec.name}!${cell.address} 缺少必需的采集值。`);
        if (column === 2) {
          if (!validPcTime(value)) rejectRecording("INVALID_PC_TIME", `Use YYYY-MM-DD HH:mm:ss.SSS text at ${spec.name}!${cell.address}.`, `${spec.name}!${cell.address} 必须为 YYYY-MM-DD HH:mm:ss.SSS 格式的时间文本。`);
        } else if (column === spec.signalModeColumn) {
          if (typeof value !== "string" || !value.trim()) rejectRecording("INVALID_SIGNAL_MODE", `The signal mode at ${spec.name}!${cell.address} must be non-empty text.`, `${spec.name}!${cell.address} 的信号模式必须为非空文本。`);
        } else if (typeof value !== "number" || !Number.isFinite(value)) {
          rejectRecording("NON_NUMERIC_DATA", `A finite number is required at ${spec.name}!${cell.address}.`, `${spec.name}!${cell.address} 必须为有限数值，不能使用数字文本或非数字内容。`);
        }
      }
      const point = row.getCell(1).value as number;
      const deviceTime = row.getCell(spec.deviceTimeColumn).value as number;
      if (previousPoint !== undefined && point <= previousPoint) rejectRecording("POINT_ORDER", `Point numbers must increase in sheet ${spec.name}.`, `工作表「${spec.name}」的点数必须严格递增。`);
      if (previousDeviceTime !== undefined && deviceTime <= previousDeviceTime) rejectRecording("DEVICE_TIME_ORDER", `Device timestamps must increase in sheet ${spec.name}.`, `工作表「${spec.name}」的设备时间戳必须严格递增。`);
      previousPoint = point;
      previousDeviceTime = deviceTime;
      previousRow = rowNumber;
      count++;
    });
    if (count === 0) rejectRecording("NO_DATA_ROWS", `Sheet ${spec.name} has no acquisition rows.`, `工作表「${spec.name}」没有采集数据行。`);
    summary.sheets.push({ name: spec.name, rows: count });
  }
  return summary;
}


