const recordingSelect = q.select({title:"zeEkp",notes:"vJAry",details:"tK86e",status:"xdngv",file:"Isfed",recordedAt:"g6vPx",uploadedAt:"vCMiW",owner:"oXwWD",trashedAt:"p32Qm"});
const createSelect = q.select({title:"zeEkp",notes:"vJAry",details:"tK86e",status:"xdngv",file:"Isfed",recordedAt:"g6vPx",user:"XGfxf"});
const editSelect = q.select({title:"zeEkp",notes:"vJAry",details:"tK86e",recordedAt:"g6vPx",trashedAt:"p32Qm"});
const profileSelect = q.select({name:"NcdBM",email:"S7WUN"});
type Lang = "en" | "zh";
type UploadValidationSummary = {schemaVersion:string;sheets:Array<{name:string;rows:number}>};
type UploadValidationIssue = {code:string;en:string;zh:string};
const uploadValidationIssue=(issue:unknown):UploadValidationIssue=>{const value=issue as Partial<UploadValidationIssue>|null;return value&&typeof value.en==="string"&&typeof value.zh==="string"?{code:typeof value.code==="string"?value.code:"INVALID_RECORDING",en:value.en,zh:value.zh}:{code:"INVALID_RECORDING",en:"This file could not be checked. Choose an original XLSX recording exported by the acquisition system.",zh:"无法核验这份文件，请选择采集系统导出的原始 XLSX 记录。"};};
type T = (en:string,zh:string)=>string;
const plain=(v:any):string => v==null?"":typeof v==="string"?v:Array.isArray(v)?v.map(plain).join(", "):String(v.label??v.value??v.email??"");
const firstFile=(v:any):any=>{const f=Array.isArray(v)?v[0]:v;return f&&typeof f==="object"?f:null;};
const localDate=(v?:any)=>{const d=v?new Date(plain(v)):new Date();if(!Number.isFinite(d.getTime()))return "";return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const fmtDate=(v:any,lang:Lang)=>{const d=new Date(plain(v));return Number.isFinite(d.getTime())?d.toLocaleString(lang==="zh"?"zh-CN":"en-GB",{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}):"—";};
const ownerMatches=(record:any,email:string)=>plain(record?.fields?.owner).toLowerCase()===email.toLowerCase();
function withQuery(navigation:any, values:Record<string,string>){
  if (!navigation || !("destination" in navigation) || typeof navigation.destination!=="string") return navigation;
  const [beforeHash,hash=""] = navigation.destination.split("#");
  const [pathname,query=""] = beforeHash.split("?");
  const params=new URLSearchParams(query);
  Object.entries(values).forEach(([key,value])=>params.set(key,value));
  return {...navigation,destination:pathname+"?"+params.toString()+(hash?"#"+hash:"")};
}

type DailyJourneyContext={date:string;recordingId?:string;planId?:string};
function bmDayKey(value:any=new Date()):string{const d=value instanceof Date?value:new Date(plain(value));return Number.isFinite(d.getTime())?new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10):"";}
function bmValidDay(value:any):boolean{if(typeof value!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+"T12:00:00Z");return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value&&value<=bmDayKey();}
function bmReadJourney():DailyJourneyContext{const p=new URLSearchParams(window.location.search);const date=p.get("ctxDate");return {date:bmValidDay(date)?date!:bmDayKey(),recordingId:p.get("ctxRecord")||undefined,planId:p.get("ctxPlan")||undefined};}
function bmShiftDay(day:string,delta:number):string{const d=new Date(day+"T12:00:00");d.setDate(d.getDate()+delta);return bmDayKey(d);}
function bmDayLabel(day:string,lang:Lang):string{return new Date(day+"T12:00:00").toLocaleDateString(lang==="zh"?"zh-CN":"en-GB",{month:"long",day:"numeric",weekday:"long"});}
function bmRelatedIds(value:any):string[]{return (Array.isArray(value)?value:value?[value]:[]).map(x=>typeof x==="string"?x:x?.id).filter((x:any)=>typeof x==="string"&&x.length>0);}
function bmAnalysisSummary(record:any):any{try{const v=typeof record?.fields?.analysisSummary==="string"?JSON.parse(record.fields.analysisSummary):record?.fields?.analysisSummary;return v?.summary&&["success","partial"].includes(v?.execution?.status)?v:null;}catch{return null;}}
function bmRecordingState(record:any,t:T):string{const a=bmAnalysisSummary(record);return a?a.execution.status==="partial"?t("Analysed · with limitations","已分析 · 部分指标受限"):t("Analysis available","已有分析结果"):t("Uploaded · not analysed","已上传 · 尚未分析");}


function useLinks(){
  return {
    home:useNavigationSetting({name:"home-link",label:"Daily overview",initialValue:{destination:"/",openIn:"SELF"}}),
    upload:useNavigationSetting({name:"upload-page-link",label:"Upload page",initialValue:{destination:"/upload",openIn:"SELF"}}),
    report:useNavigationSetting({name:"report-page-link",label:"Summary report",initialValue:{destination:"/report",openIn:"SELF"}}),
    analysis:useNavigationSetting({name:"analysis-page-link",label:"Detailed analysis",initialValue:{destination:"/analysis",openIn:"SELF"}}),
    trash:useNavigationSetting({name:"trash-page-link",label:"Recycle bin",initialValue:{destination:"/trash",openIn:"SELF"}}),
    recordings:useNavigationSetting({name:"recordings-page-link",label:"Respiratory recordings",initialValue:{destination:"/recordings",openIn:"SELF"}}),
    assistant:useNavigationSetting({name:"assistant-page-link",label:"AI assistant",initialValue:{destination:"/assistant",openIn:"SELF"}}),
    wellbeing:useNavigationSetting({name:"wellbeing-page-link",label:"Diary, routine and visit pages",initialValue:{destination:"/wellbeing",openIn:"SELF"}}),
    learn:useNavigationSetting({name:"learn-page-link",label:"Sleep guide",initialValue:{destination:"/learn",openIn:"SELF"}}),
    settings:useNavigationSetting({name:"preferences-page-link",label:"Preferences",initialValue:{destination:"/preferences",openIn:"SELF"}}),
    security:useNavigationSetting({name:"security-page-link",label:"Security centre",initialValue:{destination:"/security",openIn:"SELF"}}),
    account:useNavigationSetting({name:"account-link",label:"Account settings",initialValue:{destination:"/account",openIn:"SELF"}}),
    login:useNavigationSetting({name:"login-link",label:"Log in",initialValue:{destination:"/login",openIn:"SELF"}}),
    signup:useNavigationSetting({name:"signup-link",label:"Create account",initialValue:{destination:"/sign-up",openIn:"SELF"}}),
    password:useNavigationSetting({name:"password-link",label:"Password reset",initialValue:{destination:"/forgot-password",openIn:"SELF"}}),
  };
}
function NavLink({to,children,className="bm-button secondary",record,...props}:any){return <NavigationAction navigation={to} className={className} {...(record?{recordId:record.id,datasourceId:"recordings"}:{})} {...props}>{children}</NavigationAction>;}
function FileLink({record,t}:any){return <PrivateFileLink file={firstFile(record.fields.file)} recordId={record.id} t={t}/>;}
function Empty({title,children,icon}:any){return <div className="bm-empty">{icon??<FileText size={34}/>}<h2>{title}</h2>{children}</div>;}

function PrimaryNavigation({t,links}:any){
 const readView=()=>new URLSearchParams(window.location.search).get("view")||"diary";
 const [view,setView]=useState(readView);
 useEffect(()=>{const changed=()=>setView(readView());window.addEventListener("breathmap:tool-route-changed",changed);return()=>window.removeEventListener("breathmap:tool-route-changed",changed);},[]);
 const toolSection=["monitoring","trends"].includes(view)?"recordings":["routine","relax"].includes(view)?"routine":view==="visits"?"visits":"daily";
 const section=PAGE==="wellbeing"?toolSection:["recordings","upload","report","analysis","trash"].includes(PAGE)?"recordings":PAGE;
 const daily=(id:string)=>withQuery(links.wellbeing,{view:id,ctxDate:bmReadJourney().date});
 const recordingsLink=links.recordings;
 const assistantQuery=new URLSearchParams(window.location.search);
 const assistantRecord=assistantQuery.get("recordId")||assistantQuery.get("record")||assistantQuery.get("ctxRecord");
 const assistantLink=withQuery(links.assistant,{ctxDate:bmReadJourney().date,...(assistantRecord?{recordId:assistantRecord}:{})});
 const items=[
  {id:"home",en:"Home",zh:"个人首页",to:links.home,page:"home"},
  {id:"recordings",en:"Recordings",zh:"呼吸记录",to:recordingsLink,page:"recordings"},
  {id:"assistant",en:"AI assistant",zh:"AI 助手",to:assistantLink,page:"assistant"},
  {id:"daily",en:"Diary & checks",zh:"日记与自测",to:daily("diary"),view:"diary"},
  {id:"routine",en:"Routine & relaxation",zh:"作息与放松",to:daily("routine"),view:"routine"},
  {id:"visits",en:"Visit notes",zh:"就诊资料",to:daily("visits"),view:"visits"},
  {id:"learn",en:"Sleep guide",zh:"睡眠知识",to:links.learn,page:"learn"},
 ];
 const toolClick=(item:any)=>window.dispatchEvent(new window.CustomEvent("breathmap:tool-select",{detail:item.view?{view:item.view}:{page:item.page}}));
 const recordingItems=[
  {id:"history",en:"Saved recordings",zh:"历史记录",to:recordingsLink,page:"recordings",active:PAGE==="recordings"||["report","analysis","trash"].includes(PAGE)},
  {id:"upload",en:"Upload recording",zh:"上传记录",to:links.upload,page:"upload",active:PAGE==="upload"},
  {id:"monitoring",en:"Recording plan",zh:"采集计划",to:daily("monitoring"),view:"monitoring",active:PAGE==="wellbeing"&&view==="monitoring"},
  {id:"trends",en:"Trends and comparisons",zh:"趋势与对比",to:daily("trends"),view:"trends",active:PAGE==="wellbeing"&&view==="trends"},
 ];
 const renderItem=(item:any,active:boolean)=>PAGE==="wellbeing"?<button key={item.id} type="button" aria-current={active?"page":undefined} onClick={()=>toolClick(item)}>{t(item.en,item.zh)}</button>:<NavLink key={item.id} to={item.to} className="" aria-current={active?"page":undefined}>{t(item.en,item.zh)}</NavLink>;
 return <>
  <nav className="wm-primary-nav" aria-label={t("Main navigation","主要导航")}>{items.map(item=>renderItem(item,section===item.id))}</nav>
  {section==="recordings"&&<nav className="wm-recording-nav" aria-label={t("Recording navigation","呼吸记录导航")}>{recordingItems.map(item=>renderItem(item,item.active))}</nav>}
 </>;
}

export default function Block(){
  const user=useCurrentUser();const email=(user?.email??"").toLowerCase();const links=useLinks();const navigate=useNavigation();const currentId=useCurrentRecordId();
  const brand=useTextSetting({name:"brand",label:"Brand",initialValue:"BreathMap"});
  const [lang,setLang]=useState<Lang>(()=>{try{return localStorage.getItem("breathmap-language")==="en"?"en":"zh";}catch{return "zh";}});
  const [panel,setPanel]=useState<null|"account"|"settings"|"security"|"privacy"|"terms">(null);
  const [menu,setMenu]=useState(false);const menuRef=useRef<HTMLDivElement>(null);const menuButton=useRef<HTMLButtonElement>(null);
  const menuInitialFocus=useRef<"first"|"last">("first");const panelTrigger=useRef<HTMLElement|null>(null);
  const [detailVersion,setDetailVersion]=useState(0);const [search,setSearch]=useState("");const [message,setMessage]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);
  const [announcement,setAnnouncement]=useState("");
  const [dialog,setDialog]=useState<null|{kind:"edit"|"trash"|"delete";record:any}>(null);
  const [title,setTitle]=useState("");const [recordedAt,setRecordedAt]=useState(localDate());const [details,setDetails]=useState("");const [notes,setNotes]=useState("");
  const [file,setFile]=useState<File|null>(null);const [savedRecord,setSavedRecord]=useState<any>(null);const [dragging,setDragging]=useState(false);const fileRef=useRef<HTMLInputElement>(null);
  const [fileCheckStatus,setFileCheckStatus]=useState<"idle"|"checking"|"valid"|"invalid">("idle");
  const [fileCheckSummary,setFileCheckSummary]=useState<UploadValidationSummary|null>(null);const [fileCheckError,setFileCheckError]=useState<UploadValidationIssue|null>(null);
  const [uploadPhase,setUploadPhase]=useState<"idle"|"uploading"|"saving">("idle");
  const selectionId=useRef(0);const selectedFile=useRef<File|null>(null);const submitLock=useRef(false);const mounted=useRef(true);const currentEmail=useRef(email);currentEmail.current=email;
  const checkedFile=useRef<{file:File;selectionId:number;summary:UploadValidationSummary}|null>(null);
  const uploadedFile=useRef<{file:File;selectionId:number;email:string;profileId:string;attachment:{filename:string;url:string}}|null>(null);
  const previousEmail=useRef(email);
  const t:T=(en,zh)=>lang==="zh"?zh:en;
  const records=useRecords({from:ds.recordings,select:recordingSelect,count:50,where:q.text("owner").is(email||"__signed_out__"),orderBy:q.desc("uploadedAt"),enabled:!!email});
  const profiles=useRecords({from:ds.profiles,select:profileSelect,count:1,where:q.text("email").is(email||"__signed_out__"),enabled:!!email});
  const profile=profiles.data?.pages.flatMap(p=>p.items).find(p=>plain(p.fields.email).toLowerCase()===email);
  const create=useRecordCreate({from:ds.recordings,fields:createSelect});const update=useRecordUpdate({from:ds.recordings,fields:editSelect});const remove=useRecordDelete({from:ds.recordings});const {uploadAsync,isUploading}=useUpload();
  const items=(records.data?.pages.flatMap(p=>p.items)??[]).filter(r=>ownerMatches(r,email));const active=items.filter(r=>!plain(r.fields.trashedAt));const trashed=items.filter(r=>!!plain(r.fields.trashedAt));
  const total=records.data?.pages[0]?.total??items.length;
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;selectionId.current++;};},[]);
  useEffect(()=>{if(previousEmail.current===email)return;previousEmail.current=email;selectionId.current++;selectedFile.current=null;checkedFile.current=null;uploadedFile.current=null;setFile(null);setSavedRecord(null);setFileCheckStatus("idle");setFileCheckSummary(null);setFileCheckError(null);if(fileRef.current)fileRef.current.value="";},[email]);
  useEffect(()=>{try{localStorage.setItem("breathmap-language",lang);}catch{}},[lang]);
  useEffect(()=>{
    if(!menu)return;
    const wrapper=menuRef.current;
    const entries=wrapper?.querySelectorAll<HTMLElement>("nav button:not(:disabled), nav a[href]");
    if(entries?.length)entries[menuInitialFocus.current==="last"?entries.length-1:0].focus();
    const outside=(event:Event)=>{if(wrapper&&!event.composedPath().includes(wrapper)&&!wrapper.contains(event.target as Node))setMenu(false);};
    document.addEventListener("pointerdown",outside);document.addEventListener("focusin",outside);
    return()=>{document.removeEventListener("pointerdown",outside);document.removeEventListener("focusin",outside);};
  },[menu]);
  function menuKey(event:ReactKeyboardEvent<HTMLDivElement>){
    if(!menu)return;
    if(event.key==="Escape"){event.preventDefault();event.stopPropagation();setMenu(false);menuButton.current?.focus();return;}
    if(!["ArrowDown","ArrowUp","Home","End"].includes(event.key))return;
    const entries=Array.from(menuRef.current?.querySelectorAll<HTMLElement>("nav button:not(:disabled), nav a[href]")??[]);
    if(!entries.length)return;
    const index=entries.indexOf(event.target as HTMLElement);
    const next=event.key==="Home"?0:event.key==="End"?entries.length-1:(index+(event.key==="ArrowDown"?1:-1)+entries.length)%entries.length;
    event.preventDefault();entries[next].focus();
  }
  function openPanel(next:NonNullable<typeof panel>,trigger?:HTMLElement){panelTrigger.current=trigger??menuButton.current;setMenu(false);setPanel(next);}
  const resetMessages=()=>{setMessage("");setError("");setAnnouncement("");};
  function openDialog(kind:"edit"|"trash"|"delete",record:any){if(busy||!ownerMatches(record,email))return;resetMessages();if(kind==="edit"){setTitle(plain(record.fields.title));setRecordedAt(localDate(record.fields.recordedAt));setDetails(plain(record.fields.details));setNotes(plain(record.fields.notes));}setDialog({kind,record});}
  async function chooseFile(next:File|null){
    if(submitLock.current||busy||isUploading)return;
    const id=++selectionId.current;selectedFile.current=next;checkedFile.current=null;uploadedFile.current=null;
    resetMessages();setSavedRecord(null);setFile(next);setFileCheckSummary(null);setFileCheckError(null);setFileCheckStatus(next?"checking":"idle");
    if(!next){if(fileRef.current)fileRef.current.value="";return;}
    try{
      const summary=await validateRecordingFile(next);
      if(!mounted.current||id!==selectionId.current||selectedFile.current!==next)return;
      checkedFile.current={file:next,selectionId:id,summary};setFileCheckSummary(summary);setFileCheckStatus("valid");setTitle(previous=>previous.trim()?previous:next.name.replace(/\.xlsx$/i,""));
    }catch(issue){
      if(!mounted.current||id!==selectionId.current||selectedFile.current!==next)return;
      checkedFile.current=null;setFileCheckError(uploadValidationIssue(issue));setFileCheckStatus("invalid");
    }
  }
  function validate(){if(!title.trim())return t("Enter a recording name.","请填写记录名称。");if(!recordedAt)return t("Enter the recording date and time.","请填写采集日期和时间。");const d=new Date(recordedAt);if(!Number.isFinite(d.getTime()))return t("Enter a valid date and time.","请填写有效的日期和时间。");if(d.getTime()>Date.now()+60000)return t("The recording date cannot be in the future.","采集时间不能晚于当前时间。");return "";}
  async function saveUpload(event:FormEvent){
    event.preventDefault();if(submitLock.current||busy||isUploading)return;
    submitLock.current=true;resetMessages();let written=false;
    try{
      const issue=validate();if(issue){setError(issue);return;}
      if(!profile||!create.enabled){setError(t("Your account is not ready. Refresh or sign in again.","账号尚未准备完成，请刷新或重新登录。"));return;}
      const checked=checkedFile.current;
      if(!file||file!==selectedFile.current||fileCheckStatus!=="valid"||!checked||checked.file!==file||checked.selectionId!==selectionId.current){setError(t("Choose an original XLSX recording and wait for its format check to pass.","请选择原始 XLSX 记录，并等待标准格式核验通过。"));return;}
      const snapshot={file,selectionId:checked.selectionId,email,profileId:profile.id,title:title.trim(),recordedAt:new Date(recordedAt).toISOString(),details:details.trim(),notes:notes.trim()};
      const stillCurrent=()=>mounted.current&&currentEmail.current===snapshot.email&&selectionId.current===snapshot.selectionId&&selectedFile.current===snapshot.file;
      setBusy(true);
      const cached=uploadedFile.current;
      let attachment=cached&&cached.file===snapshot.file&&cached.selectionId===snapshot.selectionId&&cached.email===snapshot.email&&cached.profileId===snapshot.profileId?cached.attachment:null;
      if(!attachment){
        setUploadPhase("uploading");
        const [uploaded]=await uploadAsync(snapshot.file);
        if(!uploaded||uploaded.status!=="completed"||!uploaded.url)throw new Error("Upload failed");
        if(!stillCurrent())throw new Error("Upload context changed");
        attachment={...uploaded,filename:uploaded.file.name,url:uploaded.url};
        uploadedFile.current={file:snapshot.file,selectionId:snapshot.selectionId,email:snapshot.email,profileId:snapshot.profileId,attachment};
      }
      if(!stillCurrent())throw new Error("Upload context changed");
      setUploadPhase("saving");
      const newRecord=await create.mutateAsync({title:snapshot.title,recordedAt:snapshot.recordedAt,details:snapshot.details,notes:snapshot.notes,user:[snapshot.profileId],file:attachment,status:"Not analysed"});
      written=true;uploadedFile.current=null;
      if(!stillCurrent())return;
      setSavedRecord(newRecord);setFile(null);selectedFile.current=null;checkedFile.current=null;setFileCheckStatus("idle");setFileCheckSummary(null);setFileCheckError(null);if(fileRef.current)fileRef.current.value="";
      await records.refetch();setMessage(t("Recording saved to your account.","记录已保存到你的账号。"));
    }catch{
      if(!mounted.current||currentEmail.current!==email)return;
      if(written)setMessage(t("Recording saved. Refresh the page to reload your history.","记录已保存，请刷新页面读取最新历史记录。"));
      else setError(uploadedFile.current?t("The file was uploaded, but the recording could not be saved. Your details are still here; retry saving without replacing the file.","文件已上传，但记录保存未完成。采集信息已保留，请直接重试保存，无需替换文件。"):t("We could not save the recording. Your form is still here; please try again.","记录保存失败，表单内容已保留，请重试。"));
    }finally{submitLock.current=false;if(mounted.current){setBusy(false);setUploadPhase("idle");}}
  }
  async function saveEdit(event:FormEvent){
    event.preventDefault();if(busy||!dialog||dialog.kind!=="edit"||!update.enabled||!ownerMatches(dialog.record,email))return;
    resetMessages();const issue=validate();if(issue){setError(issue);return;}setBusy(true);let written=false;
    try{
      await update.mutateAsync({recordId:dialog.record.id,fields:{title:title.trim(),recordedAt:new Date(recordedAt).toISOString(),details:details.trim(),notes:notes.trim()}});
      written=true;setDetailVersion(v=>v+1);setDialog(null);
      await records.refetch();setMessage(t("Changes saved.","修改已保存。"));
    }catch{
      if(written)setMessage(t("Changes saved. Refresh the page to reload your history.","修改已保存，请刷新页面读取最新历史记录。"));
      else setError(t("Changes could not be saved. Please try again.","修改保存失败，请重试。"));
    }finally{setBusy(false);}
  }
  async function changeTrash(record:any,restore=false){
    if(busy||!update.enabled||!ownerMatches(record,email))return;resetMessages();setBusy(true);let written=false;
    const success=restore?t("Recording restored.","记录已恢复。"):t("Recording moved to the recycle bin.","记录已移入回收站。");
    try{
      await update.mutateAsync({recordId:record.id,fields:{trashedAt:restore?null:new Date().toISOString()}});
      written=true;setDialog(null);await records.refetch();if(restore)setMessage(success);else setAnnouncement(success);
    }catch{
      if(written){const savedMessage=success+" "+t("Refresh the page to reload your history.","请刷新页面读取最新历史记录。");if(restore)setMessage(savedMessage);else setAnnouncement(savedMessage);}
      else setError(t("The recording could not be updated. Please try again.","记录更新失败，请重试。"));
    }finally{setBusy(false);}
  }
  async function deleteRecord(){
    if(busy||dialog?.kind!=="delete"||!remove.enabled||!ownerMatches(dialog.record,email)||!plain(dialog.record.fields.trashedAt))return;
    resetMessages();setBusy(true);let written=false;
    try{
      await remove.mutateAsync(dialog.record.id);written=true;setDialog(null);
      await records.refetch();setMessage(t("Recording permanently deleted.","记录已彻底删除。"));
    }catch{
      if(written)setMessage(t("Recording permanently deleted. Refresh the page to reload the recycle bin.","记录已彻底删除，请刷新页面读取最新回收站。"));
      else setError(t("Deletion failed. The recording remains in the recycle bin.","删除失败，记录仍保留在回收站。"));
    }finally{setBusy(false);}
  }
  function fieldForm(upload = false) {
    return <>
      {upload && <>
        <div className={`drop-zone${file ? " has-file" : ""}${dragging ? " dragover" : ""}`} onDragOver={e => {e.preventDefault();if (!submitLock.current && !busy && !isUploading) setDragging(true);}} onDragLeave={() => setDragging(false)} onDrop={e => {e.preventDefault();setDragging(false);if (submitLock.current || busy || isUploading) return;if(e.dataTransfer.files.length!==1){void chooseFile(null);setFileCheckStatus("invalid");setFileCheckError({code:"ONE_FILE_REQUIRED",en:"Choose one XLSX recording at a time.",zh:"每次请选择一份 XLSX 记录。"});return;}void chooseFile(e.dataTransfer.files[0] ?? null);}}>
          <input ref={fileRef} id="bm-file" type="file" className="sr-only" aria-label={t("Choose an XLSX recording", "选择 XLSX 记录文件")} aria-describedby="bm-file-status bm-file-help" aria-invalid={fileCheckStatus==="invalid"} accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={e => {void chooseFile(e.target.files?.[0] ?? null);}} disabled={busy || isUploading}/>
          <div className="drop-icon">{file ? <FileText size={26}/> : <Upload size={26}/>}</div>
          <h2>{file ? file.name : t("Drop your recording here", "把记录文件拖到这里")}</h2>
          <p className="small muted">{file ? `${(file.size / 1024).toFixed(1)} KB · XLSX` : t("or choose a file from your device", "或从你的设备中选择一份文件")}</p>
          <div className="button-row">
            <button type="button" className="btn secondary" onClick={() => fileRef.current?.click()} disabled={busy || isUploading}>{file ? t("Replace file", "替换文件") : t("Choose file", "选择文件")}</button>
            {file && <button type="button" className="text-button" onClick={() => {void chooseFile(null);}} disabled={busy || isUploading}>{t("Remove", "移除")}</button>}
          </div>
        </div>
        <div id="bm-file-status" aria-live="polite" aria-atomic="true">
          {fileCheckStatus==="checking"&&<p className="notice button-row" role="status"><RefreshCw size={17} className="is-loading"/>{t("Checking the recording format…","正在核验记录格式……")}</p>}
          {fileCheckStatus==="valid"&&fileCheckSummary&&<div className="notice"><p className="button-row"><Check size={17}/>{t(`Format checked · ${fileCheckSummary.sheets.length} sheets`,`格式核验通过 · ${fileCheckSummary.sheets.length} 张表`)}</p><p className="small muted">{fileCheckSummary.sheets.map(sheet=>`${sheet.name}: ${sheet.rows.toLocaleString(lang==="zh"?"zh-CN":"en-GB")} ${t("samples","条样本")}`).join(" · ")}</p></div>}
          {fileCheckStatus==="invalid"&&fileCheckError&&<p className="notice error" role="alert">{t(fileCheckError.en,fileCheckError.zh)}</p>}
        </div>
        <p id="bm-file-help" className="upload-disclaimer">{t("Keep the acquisition system's original XLSX format and both worksheets. The format check does not perform respiratory analysis.", "请保持采集系统导出的原始 XLSX 格式及两张工作表。格式核验不会进行呼吸分析。")}</p>
      </>}
      <div className={upload ? "upload-fields" : "bm-form"}>
        <div className="field"><label htmlFor="bm-title">{t("Recording name", "记录名称")}</label><input id="bm-title" value={title} onChange={e => setTitle(e.target.value)} maxLength={1024} required disabled={busy} placeholder={t("Give this recording an easy-to-recognise name", "给这份记录一个容易辨认的名字")}/></div>
        <div className="field"><label htmlFor="bm-date">{t("Recording date and time", "采集日期和时间")}</label><input id="bm-date" type="datetime-local" required value={recordedAt} onChange={e => setRecordedAt(e.target.value)} onInput={e => setRecordedAt(e.currentTarget.value)} disabled={busy}/></div>
        <div className="field"><label htmlFor="bm-details">{t("Recording details", "采集情况")} <span className="optional">{t("Optional", "选填")}</span></label><input id="bm-details" maxLength={65536} value={details} onChange={e => setDetails(e.target.value)} disabled={busy} placeholder={t("e.g. Awake, lying down, quiet environment", "例如：清醒、平躺、安静环境")}/></div>
        <div className="field"><label htmlFor="bm-notes">{t("Recording notes", "记录备注")} <span className="optional">{t("Optional", "选填")}</span></label><textarea id="bm-notes" rows={3} maxLength={65536} value={notes} onChange={e => setNotes(e.target.value)} disabled={busy} placeholder={t("Add any details you would like to keep", "写下你希望保留的说明")}/></div>
      </div>
    </>;
  }
  function learningLinks(){return <section><div className="bm-section-head"><div><h2>{t("A little more about sleep","关于睡眠，多了解一点")}</h2><p className="bm-note">{t("Choose a topic and read at your own pace.","从感兴趣的话题开始，按自己的节奏阅读。")}</p></div></div><div className="bm-form-grid">{READING.categories.map((c:any)=><NavLink key={c.id} to={withQuery(links.learn,{category:c.id})} className="bm-panel bm-article-row">{c.id==="basics"?<Moon/>:<BookOpen/>}<div><h3>{c.title[lang]}</h3><p>{c.description[lang]}</p></div><ArrowRight size={20}/></NavLink>)}</div></section>;}
  const name=user?.firstName||user?.fullName||t("there","用户");
  const filtered=(PAGE==="trash"?trashed:active).filter(r=>(plain(r.fields.title)+" "+plain(r.fields.details)+" "+plain(r.fields.notes)).toLowerCase().includes(search.trim().toLowerCase()));
  const privatePage=PAGE!=="learn";
  return <div className="bm-app" lang={lang==="zh"?"zh-CN":"en"}><style>{CSS}</style>
    <header className="app-header">
      <NavLink to={links.home} className="brand" aria-label={t("BreathMap home","BreathMap 个人首页")}><span className="brand-mark"><Activity className="icon"/></span>{brand}</NavLink>
      <div className="header-account">
        <button className="text-button language-switch" type="button" onClick={()=>setLang(lang==="en"?"zh":"en")} aria-label={t("Switch to Chinese","切换为英文")}><Globe2 className="icon"/>{t("中文","English")}</button>
        {user?<div className="account-menu-wrap" ref={menuRef} onPointerDown={event=>event.stopPropagation()} onKeyDown={menuKey}>
          <button aria-label={t("Open user menu","打开用户菜单")} ref={menuButton} className="account-button" type="button" aria-expanded={menu} aria-controls="bm-user-menu" onClick={()=>{menuInitialFocus.current="first";setMenu(!menu);}} onKeyDown={event=>{if(!menu&&(event.key==="ArrowDown"||event.key==="ArrowUp")){event.preventDefault();menuInitialFocus.current=event.key==="ArrowUp"?"last":"first";setMenu(true);}}}><UserRound className="icon"/><span>{user.fullName||t("My account","我的账号")}</span><ChevronDown className="icon"/></button>
          {menu&&<div id="bm-user-menu" className="account-popover">
            <div className="account-popover-summary"><UserRound className="icon"/><div><strong>{user.fullName||t("My account","我的账号")}</strong><p>{email}</p></div></div>
            <nav aria-label={t("User menu","用户菜单")}>
              <button type="button" onClick={()=>openPanel("account")}><UserRound className="icon"/>{t("Account information","账号信息")}</button>
              <button type="button" onClick={()=>openPanel("security")}><ShieldCheck className="icon"/>{t("Security centre","安全中心")}</button>
              <button type="button" onClick={()=>openPanel("settings")}><Settings2 className="icon"/>{t("Preferences","设置")}</button>
              <NavLink to={links.trash} className="menu-recycle" onClick={()=>setMenu(false)}><Trash2 className="icon"/>{t("Recycle bin","回收站")}<span className="count">{trashed.length}{records.hasNextPage?"+":""}</span></NavLink>
              <NavLink to={links.account} className="menu-logout" onClick={()=>setMenu(false)} title={t("Open account settings, then use the native sign-out action.","打开账号设置，再使用原生退出登录操作。")}><Settings2 className="icon"/>{t("Account settings & sign out","账号设置与退出登录")}</NavLink>
            </nav>
          </div>}
        </div>:<NavLink to={links.login} className="btn secondary">{t("Log in","登录")}</NavLink>}
      </div>
    </header>
    {user&&<PrimaryNavigation t={t} links={links}/>}
    <main id="breathmap-main" className="bm-main main-content" tabIndex={-1}>
    <p className="sr-only" role="status" aria-live="polite" aria-atomic="true">{announcement}</p>
    {privatePage&&!user?<Empty title={t("Log in to view your recordings","登录后查看你的记录")} icon={<LockKeyhole size={34}/>}><p>{t("Your files and notes belong to your account.","文件和备注保存在你的个人账号中。")}</p><div className="bm-actions"><NavLink to={links.login}>{t("Log in","登录")}</NavLink><NavLink to={links.signup}>{t("Create account","创建账号")}</NavLink></div></Empty>:<>
    {message&&<div className="bm-message" role="status"><Check size={18}/><span>{message}</span><button type="button" className="bm-button ghost" aria-label={t("Dismiss","关闭提示")} onClick={()=>setMessage("")}><X size={17}/></button></div>}
    {error&&!dialog&&<div className="bm-error" role="alert">{error}</div>}
    {PAGE === "home" && <HomeOverview key={email} lang={lang} t={t} email={email} name={name} links={links} recordings={active} recordingsStatus={records.status} recordingsHasMore={records.hasNextPage} trashedCount={trashed.length} renderHistory={(expanded:boolean)=>renderList(false,expanded?undefined:3)}/>}
    {PAGE === "recordings" && <section className="bm-recordings-page">
      <div className="page-heading"><div><h1>{t("Respiratory recordings","呼吸记录")}</h1><p className="muted">{t("Find saved recordings, review their results or upload a new file.","查找已保存的呼吸记录、回顾分析结果，或上传新的采集文件。")}</p></div><NavLink to={links.upload} className="btn"><Plus size={18}/>{t("Upload recording","上传记录")}</NavLink></div>
      <div className="bm-recording-toolbar"><label className="search-box"><Search size={18}/><input type="search" aria-label={t("Search recordings","搜索呼吸记录")} value={search} onChange={event=>setSearch(event.target.value)} placeholder={t("Search by name or notes","按名称或备注搜索")}/></label><NavLink to={links.trash} className="text-button"><Trash2 size={17}/>{t("Recycle bin","回收站")}</NavLink></div>
      {renderList(false)}
      {records.status==="success"&&!filtered.length&&!records.hasNextPage&&<Empty title={search.trim()?t("No matching recordings","没有找到匹配的记录"):t("No recordings saved yet","还没有保存呼吸记录")}><p>{search.trim()?t("Try another name or clear the search.","换一个名称搜索，或清空搜索内容。"):t("Upload an original XLSX file to start a recording.","上传原始 XLSX 文件，建立第一份呼吸记录。")}</p></Empty>}
    </section>}
    {PAGE === "upload" && <>
      <NavLink to={links.recordings} className="back-link"><ArrowLeft size={17}/>{t("Saved recordings", "历史记录")}</NavLink>
      <div className="page-heading"><div><h1>{t("Upload a new recording", "上传一份新的记录")}</h1><p className="muted">{t("Add the details you want to remember about this recording.", "补充你希望保留的采集信息。")}</p></div></div>
      {savedRecord ? <section className="progress-panel">
        <span className="progress-symbol"><Check size={38}/></span>
        <h2>{t("Recording saved", "记录已保存")}</h2>
        <p>{t("Your file and recording details are saved to your account. Analysis is not available yet.", "文件及采集信息已保存到你的账号，分析功能尚未开放。")}</p>
        <div className="button-row">
          {savedRecord.id && <NavLink to={links.report} record={savedRecord} className="btn">{t("View recording", "查看记录")}<ArrowRight size={18}/></NavLink>}
          <NavLink to={links.recordings} className="btn secondary">{t("Back to recordings", "返回呼吸记录")}</NavLink>
          <button type="button" className="text-button" disabled={busy||isUploading} onClick={() => {if(submitLock.current||busy||isUploading)return;selectionId.current++;selectedFile.current=null;checkedFile.current=null;uploadedFile.current=null;setSavedRecord(null);setFile(null);setFileCheckStatus("idle");setFileCheckSummary(null);setFileCheckError(null);setTitle("");setRecordedAt(localDate());setDetails("");setNotes("");resetMessages();}}>{t("Upload another", "继续上传")}</button>
        </div>
      </section> : <div className="upload-layout">
        <section className="upload-main">
          <ol className="stepper" aria-label={t("Recording workflow", "记录处理流程")}>
            <li className="current" aria-current="step"><span>1</span>{t("Choose recording", "选择记录")}</li>
            <li><span>2</span>{t("Analyse", "分析处理")}</li>
            <li><span>3</span>{t("Review report", "查看报告")}</li>
          </ol>
          <form onSubmit={saveUpload} aria-busy={busy || isUploading}>
            {fieldForm(true)}
            {profiles.status === "error" && <p className="notice error" role="alert">{t("Account details could not be loaded. Refresh before uploading.", "账号信息读取失败，请刷新后再上传。")}</p>}
            <div className="submit-row">
              <NavLink to={links.home} className="text-button">{t("Back to home", "返回首页")}</NavLink>
              <button className="btn" type="submit" disabled={busy || isUploading || fileCheckStatus!=="valid" || !file || !profile || !create.enabled}>{busy || isUploading || fileCheckStatus==="checking" ? <RefreshCw size={18} className="is-loading"/> : null}{fileCheckStatus==="checking"?t("Checking format…","正在核验格式……"):uploadPhase==="uploading"||isUploading?t("Uploading…", "正在上传……"):busy?t("Saving…", "正在保存……"):uploadedFile.current?.file===file&&file?t("Retry saving","重试保存"):t("Save recording", "保存记录")}<ArrowRight size={18}/></button>
            </div>
          </form>
        </section>
        <aside className="upload-aside">
          <span className="eyebrow">{t("BEFORE YOU START", "开始之前")}</span>
          <h2>{t("Make your recording easier to revisit", "让记录更容易回顾")}</h2>
          <p>{t("Choose a clear name and add the collection details you remember.", "使用清楚的名称，补充你记得的采集情况。")}</p>
          <hr/>
          <div><FileText size={20}/><p>{t("Upload one original XLSX recording with both worksheets. Current file limit: 50 MB.", "每次上传一份包含两张工作表的原始 XLSX 记录，当前单文件上限为 50 MB。")}</p></div>
          <div><RotateCcw size={20}/><p>{t("Reopen your recording from your personal dashboard at any time.", "保存后，可以随时回首页重新查看。")}</p></div>
          <div><Activity size={20}/><p>{t("Analysis and reports will be available after the analysis service is connected.", "接入分析服务后，才会生成分析结果和报告。")}</p></div>
        </aside>
      </div>}
    </>}
    {(PAGE==="report"||PAGE==="analysis")&&(currentId?<RecordingView key={currentId+":"+detailVersion} recordId={currentId} mode={PAGE} lang={lang} t={t} email={email} links={links} edit={(r:any)=>openDialog("edit",r)} update={update} refresh={()=>records.refetch()}/>:<Empty title={t("Choose a recording first","请先选择一条记录")}><NavLink to={links.recordings}>{t("Go to saved recordings","前往历史记录")}</NavLink></Empty>)}
    {PAGE==="trash"&&<><NavLink to={links.recordings} className="back-link"><ArrowLeft className="icon"/>{t("Saved recordings","历史记录")}</NavLink><div className="page-heading"><div><p className="eyebrow">{t("RECORDING MANAGEMENT","记录管理")}</p><h1>{t("Recycle bin","回收站")} <span className="count">{trashed.length}{records.hasNextPage?"+":""}</span></h1><p className="muted">{t("Restore recordings and keep their details and notes.","找回移除的记录，继续查看原有信息与备注。")}</p></div></div>{renderList(true)}<p className="small muted trash-footnote">{t("This version does not automatically empty the recycle bin. Permanent deletion cannot be undone in BreathMap.","当前版本不会自动清空回收站。彻底删除后，无法在 BreathMap 中恢复。")}</p></>}
    {PAGE==="wellbeing"&&<WellbeingPage key={email} lang={lang} t={t} email={email} profile={profile} recordings={active} recordingsStatus={records.status} recordingsHasMore={records.hasNextPage} loadMoreRecordings={()=>records.fetchNextPage()} links={links}/>}
    {PAGE==="learn"&&<ReadingLibrary lang={lang} t={t} links={links}/>}
    {PAGE==="settings"&&<><NavLink to={links.home} className="bm-back"><ArrowLeft size={17}/>{t("My recordings","我的记录")}</NavLink><h1 className="bm-title">{t("Preferences","设置")}</h1><section className="bm-panel"><div className="bm-settings-row"><div><h2>{t("Language","界面语言")}</h2><p className="bm-note">{t("Applied to BreathMap pages on this browser.","应用于此浏览器中的 BreathMap 页面。")}</p></div><select className="bm-input" aria-label={t("Language","语言")} value={lang} onChange={e=>setLang(e.target.value as Lang)}><option value="en">English</option><option value="zh">简体中文</option></select></div><div className="bm-settings-row"><div><h2>{t("Account information","账号信息")}</h2><p className="bm-note">{t("Manage your profile and account details.","管理个人资料和账号信息。")}</p></div><NavLink to={links.account}>{t("Open account settings","打开账号设置")}</NavLink></div><div className="bm-settings-row"><div><h2>{t("Recording management","记录管理")}</h2><p className="bm-note">{t("Find recordings you moved to the recycle bin.","查看已移入回收站的记录。")}</p></div><NavLink to={links.trash}>{t("Open recycle bin","打开回收站")}</NavLink></div></section></>}
    {PAGE==="security"&&<><NavLink to={links.home} className="bm-back"><ArrowLeft size={17}/>{t("My recordings","我的记录")}</NavLink><h1 className="bm-title">{t("Security centre","安全中心")}</h1><section className="bm-panel"><div className="bm-settings-row"><div><h2>{t("Account email","账号邮箱")}</h2><p className="bm-file-name">{email}</p></div><NavLink to={links.account}>{t("Manage account","管理账号")}</NavLink></div><div className="bm-settings-row"><div><h2>{t("Password","登录密码")}</h2><p className="bm-note">{t("Change your password through account settings, or request a reset.","在账号设置中修改密码，或申请重置密码。")}</p></div><div className="bm-actions"><NavLink to={links.account}>{t("Account settings","账号设置")}</NavLink><NavLink to={links.password}>{t("Reset password","重置密码")}</NavLink></div></div><div className="bm-settings-row"><div><h2>{t("Phone binding","手机绑定")}</h2><p className="bm-note">{t("Phone verification is not enabled.","手机验证尚未启用。")}</p></div><button className="bm-button secondary" disabled>{t("Not available yet","暂未开放")}</button></div></section></>}
    </>}
    </main><footer className="app-footer"><span>{brand} · {t("Respiratory recording analysis","呼吸记录分析")}</span><span className="footer-links"><button type="button" className="text-button" onClick={event=>openPanel("privacy",event.currentTarget)}>{t("Privacy information","隐私说明")}</button><button type="button" className="text-button" onClick={event=>openPanel("terms",event.currentTarget)}>{t("Terms of use","使用条款")}</button></span></footer>
    <Dialog open={!!panel} onOpenChange={open=>{if(!open)setPanel(null);}}><DialogContent className="bm-app" lang={lang==="zh"?"zh-CN":"en"} onCloseAutoFocus={event=>{event.preventDefault();(panelTrigger.current?.isConnected?panelTrigger.current:menuButton.current)?.focus();}}><style>{CSS}</style><DialogHeader><DialogTitle>{panel==="account"?t("Account information","账号信息"):panel==="security"?t("Security centre","安全中心"):panel==="privacy"?t("Privacy information","隐私说明"):panel==="terms"?t("Terms of use","使用条款"):t("Preferences","设置")}</DialogTitle><DialogDescription>{panel==="settings"?t("Choose how BreathMap appears on this browser.","设置当前浏览器中的 BreathMap 界面。"):panel==="privacy"?t("How this version stores your information.","当前版本如何保存你的信息。"):panel==="terms"?t("Available features and limits of the current version.","当前版本可用的功能及其限制。"):t("Your account is managed by Supabase Auth.","你的账号由 Supabase Auth 管理。")}</DialogDescription></DialogHeader>
    {panel==="privacy"&&<div className="dialog-body"><p>{t("Sleep diaries, recording plans, sleep routines, visit notes and saved reaction-check results are stored in your account. Wind-down preferences are saved with your profile. These entries are not automatically sent to a language model.","睡眠日记、采集计划、作息计划、就诊资料与保存的反应自测结果会关联账号保存。放松偏好保存在个人资料中。这些内容不会自动发送给语言模型。")}</p><p>{t("Uploaded XLSX files are stored in a private Supabase Storage bucket. Recording details and notes are saved in the BreathMap database and linked to your account.","上传的 XLSX 文件保存在 Supabase Storage 私有存储空间中。采集信息与备注保存在 BreathMap 数据库中，并关联你的账号。")}</p><p>{t("Recording access is restricted to the associated account. Your language preference is saved in this browser when local storage is available.","记录按所属账号设置访问权限。浏览器允许本地存储时，会记住你的语言选择。")}</p><p>{t("Approved recordings are downloaded to the analysis host for processing. When AI reports or questions are authorised, necessary structured analysis results and question content may be sent to DeepSeek. Uploading alone does not start analysis or an AI request. Raw workbooks are not sent through the current report or question interfaces.","经批准的记录会下载至分析主机进行处理。经授权生成 AI 报告或提问时，必要的结构化分析结果及问题内容可能发送给 DeepSeek。仅上传文件不会启动分析或 AI 请求。现有报告及问答接口不会发送原始工作簿。")}</p><p>{t("Moving a recording to the recycle bin allows it to be restored. Permanent deletion removes the cloud database record and its stored files and cannot be undone in BreathMap. This action does not guarantee deletion of analysis copies on the local host or platform backups.","移入回收站的记录可以恢复。彻底删除会移除云端数据库记录及其存储文件，无法在 BreathMap 中撤销。该操作不保证清除分析主机上的本地分析副本或平台备份。")}</p><p className="small muted">{t("The current version is for functional testing. Use non-sensitive test files until data retention and deletion arrangements are confirmed.","当前版本用于功能测试。在数据保留及删除安排确定前，请使用不含敏感信息的测试文件。")}</p></div>}
    {panel==="terms"&&<div className="dialog-body"><p>{t("BreathMap supports account access, private XLSX storage, recording details, notes, retrieval and recycle-bin actions. Uploading a file saves it; analysis must be requested separately.","BreathMap 支持账号访问、XLSX 私有存储、采集信息、备注、记录回顾及回收站操作。上传文件只会保存文件，分析需另行提交请求。")}</p><p>{t("When the analysis host is available, submitted analysis tasks can provide saved metrics, classifications, analysis windows and interactive waveforms. AI reports and questions require separate consent. Unavailable results do not indicate normal breathing.","分析主机可用时，提交的分析任务可以生成已保存的指标、分类、分析窗口及可交互波形。AI 报告与问答需另行授权。暂无分析结果不代表呼吸正常。")}</p><p>{t("Sleep articles provide general information. The website does not currently provide a medical assessment or diagnosis.","睡眠文章提供一般知识。目前网站不提供医疗评估或诊断。")}</p><p>{t("You should have permission to upload any recording you use for testing. Formal service terms and data-handling arrangements will be confirmed before real health data is used.","请确认你有权上传用于测试的记录。在使用真实健康数据前，将进一步确定正式服务条款与数据处理安排。")}</p></div>}

    {panel==="account"&&<><div className="account-detail"><UserRound size={30}/><div><h3>{user?.fullName}</h3><p className="muted small">{email}</p></div></div><dl className="profile-fields"><div><dt>{t("Display name","显示名称")}</dt><dd>{user?.fullName||"—"}</dd></div><div><dt>{t("Email address","邮箱地址")}</dt><dd>{email}</dd></div><div><dt>{t("Record storage","记录保存位置")}</dt><dd>{t("Your BreathMap account","你的 BreathMap 账号")}</dd></div></dl><NavLink to={links.account} className="btn secondary">{t("Manage account","管理账号")}</NavLink></>}
    {panel==="settings"&&<><div className="field"><label htmlFor="bm-settings-language">{t("Language","界面语言")}</label><select id="bm-settings-language" value={lang} onChange={e=>setLang(e.target.value as Lang)}><option value="en">English</option><option value="zh">简体中文</option></select><p className="small muted">{t("Applies immediately to BreathMap pages on this browser.","立即应用于此浏览器中的 BreathMap 页面。")}</p></div><div className="settings-records"><h3>{t("Recording management","记录管理")}</h3><p className="small muted">{t("Recordings in the recycle bin can be restored.","移入回收站的记录可以恢复。")}</p><NavLink to={links.trash} className="text-button"><Trash2 size={17}/>{t("Open recycle bin","打开回收站")}</NavLink></div></>}
    {panel==="security"&&<div className="security-list"><div className="security-row"><div><h3>{t("Account email","账号邮箱")}</h3><p>{email}</p></div><NavLink to={links.account} className="btn secondary">{t("Manage account","管理账号")}</NavLink></div><div className="security-row"><div><h3>{t("Phone binding","手机绑定")}</h3><p>{t("Phone verification is not enabled.","手机验证尚未启用。")}</p></div><button className="btn secondary" disabled>{t("Not available yet","暂未开放")}</button></div><div className="security-row"><div><h3>{t("Password","登录密码")}</h3><p>{t("Use account settings or request a reset.","在账号设置中修改，或申请重置。")}</p></div><div className="button-row"><NavLink to={links.account} className="btn secondary">{t("Account settings","账号设置")}</NavLink><NavLink to={links.password} className="text-button">{t("Reset password","重置密码")}</NavLink></div></div></div>}
    </DialogContent></Dialog>
    <Dialog open={!!dialog} onOpenChange={open=>{if(!open&&!busy){setDialog(null);setError("");}}}><DialogContent className="bm-app" lang={lang==="zh"?"zh-CN":"en"}><style>{CSS}</style><DialogHeader><DialogTitle>{dialog?.kind==="edit"?t("Edit recording","编辑记录"):dialog?.kind==="trash"?t("Move to recycle bin?","移入回收站？"):t("Permanently delete this recording?","彻底删除这条记录？")}</DialogTitle><DialogDescription>{dialog?.kind==="edit"?t("Update the recording details and notes. The original file stays unchanged.","更新采集信息和备注，原始文件保持不变。"):dialog?.kind==="trash"?t("You can restore it from the recycle bin later.","之后可以从回收站恢复这条记录。"):t("This removes the saved record and cannot be undone from this app.","这会删除已保存的记录，无法在本应用中恢复。")}</DialogDescription></DialogHeader>{dialog?.kind==="edit"?<form className="bm-form" onSubmit={saveEdit}>{fieldForm()}{error&&<div className="bm-error" role="alert">{error}</div>}<div className="bm-actions"><button type="button" className="bm-button secondary" onClick={()=>{setDialog(null);setError("");}} disabled={busy}>{t("Cancel","取消")}</button><button type="submit" className="bm-button" disabled={busy||!update.enabled}>{busy?t("Saving…","正在保存……"):t("Save changes","保存修改")}</button></div></form>:<><p className="bm-file-name"><strong>{plain(dialog?.record.fields.title)}</strong></p>{error&&<div className="bm-error" role="alert">{error}</div>}<div className="bm-actions"><button type="button" className="bm-button secondary" onClick={()=>{setDialog(null);setError("");}} disabled={busy}>{t("Cancel","取消")}</button><button type="button" className={`bm-button ${dialog?.kind==="delete"?"danger":""}`} disabled={busy||(dialog?.kind==="delete"?!remove.enabled:!update.enabled)} onClick={()=>dialog?.kind==="trash"?changeTrash(dialog.record):deleteRecord()}>{busy?t("Saving…","正在处理……"):dialog?.kind==="trash"?t("Move to recycle bin","确认移入回收站"):t("Permanently delete","确认彻底删除")}</button></div></>}</DialogContent></Dialog>
  </div>;
  function renderList(inTrash: boolean, limit?:number) {
    const allRows = inTrash ? trashed : active;
    const rows = limit===undefined?allRows:allRows.slice(0,limit);
    if (records.status === "error") return <div className="notice error" role="alert">{t("Recordings could not be loaded.", "记录读取失败。")}<button type="button" className="text-button" onClick={() => records.refetch()}>{t("Try again", "重试")}</button></div>;
    if (records.status === "pending") return <p className="notice" role="status">{t("Loading your recordings…", "正在读取你的记录……")}</p>;
    if (rows.length === 0 && records.hasNextPage) return <div className="empty-inline"><p>{t("No matching recordings in the loaded history. Load more to check earlier records.","已加载的历史中没有对应记录，可继续加载较早的记录。")}</p><button type="button" className="btn secondary" onClick={()=>records.fetchNextPage()} disabled={records.isFetchingNextPage}>{records.isFetchingNextPage?t("Loading…","正在读取……"):t("Load more recordings","加载更多记录")}</button></div>;
    if (rows.length === 0) return inTrash ? <section className="empty-state"><span className="empty-icon"><Trash2 size={32}/></span><h2>{t("Your recycle bin is empty", "回收站为空")}</h2><p>{t("Recordings moved here can be restored later.", "移入这里的记录可以恢复。")}</p><NavLink to={links.recordings} className="btn secondary">{t("Back to recordings", "返回呼吸记录")}</NavLink></section> : null;
    if(inTrash)return <>
      <div className="trash-list">{rows.map(r=><div className="trash-row" key={r.id}>
        <span className="record-icon"><FileText className="icon"/></span>
        <div className="trash-record-copy"><h2>{plain(r.fields.title)}</h2><p>{t("Recorded: ","采集时间：")}{fmtDate(r.fields.recordedAt,lang)}</p><p>{t("Moved: ","移入时间：")}{fmtDate(r.fields.trashedAt,lang)}</p></div>
        <span className="status neutral">{t("Not analysed","尚未分析")}</span>
        <div className="trash-actions"><button type="button" className="btn secondary" disabled={busy||!update.enabled} onClick={()=>changeTrash(r,true)} aria-label={t(`Restore ${plain(r.fields.title)}`,`恢复${plain(r.fields.title)}`)}><RotateCcw className="icon"/>{t("Restore recording","恢复记录")}</button><button type="button" className="btn quiet danger-button" disabled={busy||!remove.enabled} onClick={()=>openDialog("delete",r)} aria-label={t(`Permanently delete ${plain(r.fields.title)}`,`彻底删除${plain(r.fields.title)}`)}><Trash2 className="icon"/>{t("Permanently delete","彻底删除")}</button></div>
      </div>)}</div>
      {records.hasNextPage&&<div className="button-row"><button type="button" className="btn secondary" onClick={()=>records.fetchNextPage()} disabled={records.isFetchingNextPage}>{records.isFetchingNextPage?t("Loading…","正在读取……"):t("Load more recordings","加载更多记录")}</button></div>}
    </>;
    return <>
      <div className="record-list">{rows.map(r => <div className="record-row" key={r.id}>
        <NavLink to={links.report} record={r} className="record-open">
          <span className="record-icon"><FileText size={20}/></span>
          <span className="record-name"><strong>{plain(r.fields.title)}</strong><span>{fmtDate(r.fields.recordedAt, lang)} · {plain(r.fields.details) || t("No recording details added", "未填写采集情况")}</span></span>
          <span className="status neutral">{t("Not analysed", "尚未分析")}</span>
          <span className="row-arrow"><ArrowRight size={18}/></span>
        </NavLink>
        <button type="button" className="record-delete" disabled={busy || !update.enabled} onClick={() => openDialog("trash", r)} aria-label={t(`Move ${plain(r.fields.title)} to recycle bin`, `将${plain(r.fields.title)}移入回收站`)}><Trash2 size={16}/>{t("Move to recycle bin", "移入回收站")}</button>
      </div>)}</div>
      {records.hasNextPage && limit===undefined && <div className="button-row"><button type="button" className="btn secondary" onClick={() => records.fetchNextPage()} disabled={records.isFetchingNextPage}>{records.isFetchingNextPage ? t("Loading…", "正在读取……") : t("Load more recordings", "加载更多记录")}</button></div>}
    </>;
  }

}

/* Report and analysis retain the HTML prototype structure; no analysis is fabricated. */
function RecordingView({ recordId, mode, lang, t, email, links, edit, update, refresh }: any) {
  const record = useRecord({ from: ds.recordings, select: recordingSelect, recordId });
  const [notes, setNotes] = useState("");
  const [dirty, setDirty] = useState(false);
  const [editingNotes, setEditingNotes] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [metricInfo, setMetricInfo] = useState<"rate" | "flow" | "quality" | null>(null);

  useEffect(() => {
    if (record.data && !dirty) setNotes(plain(record.data.fields.notes));
  }, [record.data, dirty]);

  const back = mode === "analysis" ? links.report : links.recordings;
  const backLabel = mode === "analysis" ? t("Back to report", "返回报告") : t("Saved recordings", "历史记录");

  if (record.status === "pending") {
    return <div className="notice" role="status">{t("Loading recording…", "正在读取记录……")}</div>;
  }
  if (record.status === "error") {
    return <Empty title={t("This recording could not be opened", "暂时无法打开这条记录")}>
      <button type="button" className="btn" onClick={() => record.refetch()}>{t("Try again", "重试")}</button>
      <NavLink to={links.recordings} className="btn secondary">{t("Saved recordings", "历史记录")}</NavLink>
    </Empty>;
  }

  const r = record.data;
  if (!r || !ownerMatches(r, email)) {
    return <Empty title={t("Recording not found", "未找到记录")}>
      <NavLink to={links.recordings} className="btn secondary">{t("Saved recordings", "历史记录")}</NavLink>
    </Empty>;
  }
  if (plain(r.fields.trashedAt)) {
    return <Empty title={t("This recording is in the recycle bin", "这条记录已移入回收站")} icon={<Trash2 size={32} />}>
      <NavLink to={links.trash} className="btn secondary">{t("Open recycle bin to restore it", "前往回收站恢复")}</NavLink>
    </Empty>;
  }

  async function saveNotes(event: FormEvent) {
    event.preventDefault();
    if (saving || !update.enabled || !ownerMatches(r, email) || plain(r.fields.trashedAt)) return;
    setSaving(true);
    setMessage("");
    setError("");
    let written = false;
    try {
      await update.mutateAsync({ recordId: r.id, fields: { notes } });
      written = true;
      await record.refetch();
      await refresh();
      setDirty(false);
      setEditingNotes(false);
      setMessage(t("Notes saved.", "备注已保存。"));
    } catch {
      if (written) setMessage(t("Notes saved. Refresh the page to reload the latest record.", "备注已保存，请刷新页面重新读取最新记录。"));
      else setError(t("Your notes could not be saved. Please try again.", "备注保存失败，输入内容已保留，请重试。"));
    } finally {
      setSaving(false);
    }
  }

  function cancelNotes() {
    if (saving) return;
    setNotes(plain(r.fields.notes));
    setDirty(false);
    setEditingNotes(false);
    setError("");
  }

  const unavailable = t("Not analysed", "尚未分析");
  const relatedActions=<section className="wm-record-followup"><h2>{t("Put this recording in context","把这份记录放进日常回顾")}</h2><p className="small muted">{t("Keep your own experience alongside the recording, compare available results, or gather material for a visit. Choose the diary date yourself.","可以补充个人感受、比较已有结果，或整理就诊材料。日记日期由你确认。")}</p><div className="button-row"><NavLink to={withQuery(links.wellbeing,{view:"diary",ctxRecord:r.id})} className="btn secondary">{t("Add a linked diary","补充关联日记")}</NavLink><NavLink to={withQuery(links.wellbeing,{view:"trends",ctxRecord:r.id})} className="text-button">{t("Compare this recording","比较这份记录")}</NavLink><NavLink to={withQuery(links.wellbeing,{view:"visits",ctxRecord:r.id})} className="text-button">{t("Prepare visit materials","整理就诊材料")}</NavLink></div></section>;

  const iconInfo = <svg className="icon" viewBox="0 0 20 20" aria-hidden="true">
    <circle cx="10" cy="10" r="7.25" />
    <path d="M10 9v4M10 6.5v.1" />
  </svg>;
  const metricHelp = metricInfo === "rate" ? {
    title: t("Breathing rate", "呼吸频率"),
    body: t("The number of breaths per minute. No rate has been calculated for this recording yet.", "每分钟的呼吸次数。这条记录目前尚未计算呼吸频率。"),
  } : metricInfo === "flow" ? {
    title: t("Airflow proxy", "流速代理值"),
    body: t("A flow-related sensor metric. A physical flow rate and its unit require device calibration. No value has been calculated for this recording yet.", "与气流相关的传感器指标。物理流速及其单位需要依据设备校准结果确定。这条记录目前尚未计算该指标。"),
  } : {
    title: t("Usable analysis windows", "可分析窗口"),
    body: t("The number of analysis windows that meet the signal-quality requirements. Analysis windows and their quality have not been assessed for this recording yet.", "满足信号质量要求的分析窗口数量。这条记录目前尚未划分分析窗口或评估其质量。"),
  };

  if (mode === "analysis") {
    return <>
      <NavLink to={back} record={r} className="back-link"><ArrowLeft size={17} />{backLabel}</NavLink>
      <div className="page-heading">
        <div>
          <p className="eyebrow">{t("Detailed analysis", "详细分析")}</p>
          <h1>{plain(r.fields.title)}</h1>
          <p className="muted">{fmtDate(r.fields.recordedAt, lang)} · <span>{t("View range", "查看范围")} —</span></p>
        </div>
        <span className="status neutral">{unavailable}</span>
      </div>

      {relatedActions}
      <div className="analysis-layout">
        <section className="wave-workspace">
          <div className="section-heading">
            <h2>{t("Synchronised respiratory waveforms", "同步呼吸波形")}</h2>
            <button type="button" className="text-button" disabled><RotateCcw size={17} />{t("Reset view", "恢复整段")}</button>
          </div>
          <div className="chart-toolbar">
            <div className="button-row">
              <button type="button" className="btn quiet icon-btn" disabled aria-label={t("Move to earlier times", "向前移动时间范围")}><ArrowLeft size={20} /></button>
              <button type="button" className="btn quiet icon-btn" disabled aria-label={t("Zoom in", "放大时间轴")}><Plus size={20} /></button>
              <button type="button" className="btn quiet icon-btn" disabled aria-label={t("Zoom out", "缩小时间轴")}><span aria-hidden="true">−</span></button>
              <button type="button" className="btn quiet icon-btn" disabled aria-label={t("Move to later times", "向后移动时间范围")}><ArrowRight size={20} /></button>
            </div>
            <span className="small muted">{t("Interval selection becomes available with waveform data.", "有波形数据后，可选择时间区间。")}</span>
          </div>

          <svg className="signal-chart" viewBox="0 0 760 300" role="img" aria-label={t("Estimated expiratory flow and SIG differential voltage waveform areas. No waveform data is available.", "估计呼气流量与 SIG 差分电压波形区域，当前暂无波形数据。")}
            data-chart-width="760">
            <g className="grid-line" fill="none">
              <path d="M38 40H746M38 80H746M38 120H746M38 170H746M38 210H746M38 250H746" />
              <path d="M38 28V265M156 28V265M274 28V265M392 28V265M510 28V265M628 28V265M746 28V265" />
            </g>
            <text className="channel-title" x="43" y="21">{t("Estimated expiratory flow · L/min", "估计呼气流量 · L/min")}</text>
            <text className="channel-title" x="43" y="155">{t("SIG differential voltage · μV", "SIG 差分电压 · μV")}</text>
            <text x="392" y="84" textAnchor="middle">{t("No waveform data", "暂无波形数据")}</text>
            <text x="392" y="214" textAnchor="middle">{t("No waveform data", "暂无波形数据")}</text>
            {[38, 156, 274, 392, 510, 628, 746].map(x => <text key={x} x={x} y="289" textAnchor="middle">—</text>)}
          </svg>

          <div className="chart-legend">
            <span><i className="legend-line flow" />{t("Estimated expiratory flow", "估计呼气流量")}</span>
            <span><i className="legend-line co2" />{t("SIG differential voltage", "SIG 差分电压")}</span>
            <span><i className="legend-square" />{t("Selected window", "选中窗口")}</span>
            <span>{t("Shading: flagged interval", "阴影：关注区间")}</span>
          </div>
          <label className="range-label" htmlFor="time-position">{t("Move time range", "移动时间范围")}<span>—</span></label>
          <input id="time-position" type="range" min={0} max={0} step={1} value={0} disabled
            aria-label={t("Time range unavailable", "时间范围暂不可用")} aria-describedby="time-position-help" />
          <div className="range-ticks" aria-hidden="true">{[0, 1, 2, 3, 4].map(i => <span key={i}>—</span>)}</div>
          <p id="time-position-help" className="small muted range-help">{t("Time markers and navigation will appear when waveform data is available.", "有波形数据后，将显示时间刻度并开放区间导航。")}</p>
          <p className="small muted chart-footnote">{t("Changing the view does not alter analysis windows or run an analysis.", "查看范围不会改变分析窗口，也不会运行分析。")}</p>
        </section>

        <aside className="window-detail" aria-live="polite">
          <span className="eyebrow">{t("Current window", "当前窗口")}</span>
          <h2>—</h2>
          <span className="status neutral">{unavailable}</span>
          <dl>
            <div><dt>{t("Breathing rate", "呼吸频率")}</dt><dd>—</dd></div>
            <div><dt>{t("Airflow proxy", "流速代理值")}</dt><dd>—</dd></div>
            <div><dt>{t("Rate vs previous window", "频率较前窗")}</dt><dd>—</dd></div>
            <div><dt>{t("Flow vs previous window", "流速较前窗")}</dt><dd>—</dd></div>
          </dl>
          <div className="detail-label"><span>{t("Flagged segment count", "可疑点数量")}</span><strong>—</strong></div>
          <div className="small muted">{t("Segment explanations will appear after analysis.", "分析完成后，将显示可疑片段说明。")}</div>
          <p className="small muted window-caution">{t("No analysis result is available; breathing patterns and signal quality have not been assessed.", "目前没有分析结果，尚未判断呼吸模式或信号质量。")}</p>
          <div className="window-nav">
            <button type="button" className="btn quiet" disabled>{t("Previous window", "上一窗口")}</button>
            <button type="button" className="btn quiet" disabled>{t("Next window", "下一窗口")}</button>
          </div>
        </aside>
      </div>

      <section className="window-section">
        <div className="section-heading">
          <h2>{t("All analysis windows", "全部分析窗口")} <span className="count">—</span></h2>
          <span className="small muted">{t("Awaiting analysis", "等待分析")}</span>
        </div>
        <p className="small muted window-table-note">{t("Each window will show respiratory metrics, changes from the preceding window and any flagged segments.", "每个窗口将显示呼吸指标、较前一窗口的变化及可疑片段。")}</p>
        <table className="window-table">
          <thead><tr>
            <th scope="col">{t("Time interval", "时间区间")}</th>
            <th scope="col">{t("Breathing rate", "呼吸频率")}</th>
            <th scope="col">{t("Vs previous", "较前窗")}</th>
            <th scope="col">{t("Airflow proxy", "流速代理值")}</th>
            <th scope="col">{t("Vs previous", "较前窗")}</th>
            <th scope="col">{t("Flagged segment count", "可疑点数量")}</th>
            <th scope="col">{t("Flagged segment explanation", "可疑点说明")}</th>
          </tr></thead>
          <tbody><tr>
            <td data-label={t("Time interval", "时间区间")}><span className="muted">—</span></td>
            <td data-label={t("Breathing rate", "呼吸频率")}>—</td>
            <td data-label={t("Rate vs previous", "频率较前窗")}>—</td>
            <td data-label={t("Airflow proxy", "流速代理值")}>—</td>
            <td data-label={t("Flow vs previous", "流速较前窗")}>—</td>
            <td data-label={t("Flagged segment count", "可疑点数量")}>—</td>
            <td className="suspicious-cell" data-label={t("Flagged segment explanation", "可疑点说明")}>{t("No analysis windows available yet.", "暂无分析窗口。")}</td>
          </tr></tbody>
        </table>
        <div className="pagination">
          <span className="small muted">{t("Analysis windows: —", "分析窗口：—")}</span>
          <div className="button-row">
            <button type="button" className="btn quiet" disabled>{t("Previous", "上一页")}</button>
            <button type="button" className="btn quiet" disabled>{t("Next", "下一页")}</button>
          </div>
        </div>
      </section>
    </>;
  }

  return <>
    <NavLink to={back} className="back-link"><ArrowLeft size={17} />{backLabel}</NavLink>
    <div className="page-heading">
      <div>
        <p className="eyebrow">{t("Record report", "记录报告")}</p>
        <h1>{plain(r.fields.title)}</h1>
        <p className="muted">{fmtDate(r.fields.recordedAt, lang)} · {t("Duration", "记录时长")} —</p>
      </div>
      <NavLink to={links.analysis} record={r} className="btn secondary"><Activity size={20} />{t("Full analysis", "查看完整分析")}</NavLink>
    </div>

    <div className="metrics-strip">
      {[
        { key: "rate", title: t("Mean breathing rate", "平均呼吸频率"), unit: t("breaths/min", "次/分"), hint: t("Awaiting metric calculation", "等待指标计算") },
        { key: "flow", title: t("Mean airflow proxy", "平均流速代理值"), unit: t("proxy", "代理值"), hint: t("Physical units depend on device calibration", "物理单位依据设备校准结果确定") },
        { key: "quality", title: t("Usable analysis windows", "可分析窗口"), unit: "", hint: t("Awaiting window and quality assessment", "等待窗口划分及质量评估") },
      ].map(metric => <div key={metric.key}>
        <span>{metric.title}<button type="button" className="info-button" onClick={() => setMetricInfo(metric.key as "rate" | "flow" | "quality")} aria-label={t(`About ${metric.title}`, `了解${metric.title}`)}>{iconInfo}</button></span>
        <strong>— {metric.unit && <small>{metric.unit}</small>}</strong>
        <p>{metric.hint}</p>
      </div>)}
    </div>

    <div className="report-columns">
      {relatedActions}
    <section className="attention-section">
        <div className="section-heading"><h2>{t("Flagged intervals", "需要关注的区间")} <span className="count">—</span></h2></div>
        <div className="empty-inline">
          <h3>{t("Awaiting analysis", "等待分析")}</h3>
          <p>{t("Flagged intervals and links to their waveforms will appear after analysis. No result does not mean that the recording is normal.", "分析完成后，将显示需要关注的区间及对应波形入口。暂无结果不代表已确认记录正常。")}</p>
        </div>
        <section className="interpretation">
          <div className="section-heading"><h2>{t("Record interpretation", "本次记录解读")}</h2><span className="small muted">{unavailable}</span></div>
          <p>{t("No interpretation has been generated for this recording yet.", "这条记录目前尚未生成解读。")}</p>
          <p className="interpretation-limit">{t("Your uploaded file and notes remain saved. Analysis and AI interpretation are not connected yet.", "上传的文件与备注已保存，分析及 AI 解读功能尚未接入。")}</p>
        </section>
        <section className="interpretation" aria-labelledby="record-chat-heading">
          <div className="section-heading"><h2 id="record-chat-heading">{t("Questions about this recording", "关于这次记录的疑问")}</h2><span className="small muted">{t("Not available yet", "暂未开放")}</span></div>
          <p>{t("Recording chat will use the analysis results to answer follow-up questions. It is not connected yet.", "记录问答将结合分析结果回答后续问题，目前尚未接入。")}</p>
          <form className="auth-form" onSubmit={event => event.preventDefault()}>
            <div className="field"><label htmlFor="record-question">{t("Your question", "你的问题")}</label><textarea id="record-question" disabled rows={3} placeholder={t("Ask about your recording", "就这次记录提问")} /></div>
            <div className="button-row"><button type="submit" className="btn" disabled>{t("Send question", "发送问题")}</button></div>
          </form>
        </section>
      </section>

      <aside className="record-summary">
        <div className="section-heading"><h2>{t("Record details", "记录信息")}</h2><button type="button" className="text-button" onClick={() => edit(r)} disabled={saving || dirty || !update.enabled}>{t("Edit", "编辑")}</button></div>
        <dl>
          <div><dt>{t("Recording conditions", "采集情况")}</dt><dd>{plain(r.fields.details) || t("Not provided", "未填写")}</dd></div>
          <div><dt>{t("Record file", "记录文件")}</dt><dd>{firstFile(r.fields.file)?.filename || t("No file attached", "未附加文件")}</dd></div>
          <div><dt>{t("Data source", "数据来源")}</dt><dd>{t("Not specified", "未注明")}</dd></div>
        </dl>
        <FileLink record={r} t={t} />
        <div className="note-heading">
          <h3>{t("Personal notes", "记录备注")}</h3>
          {!editingNotes && <button type="button" className="text-button" disabled={!update.enabled} onClick={() => { setEditingNotes(true); setMessage(""); setError(""); }}>{t("Edit", "编辑")}</button>}
        </div>
        {editingNotes ? <form id="note-form" onSubmit={saveNotes} aria-busy={saving}>
          <div className="field"><label htmlFor="edit-note">{t("Notes", "备注")}</label><textarea id="edit-note" rows={5} maxLength={65536} value={notes} disabled={saving} onChange={event => { setNotes(event.target.value); setDirty(true); }} /></div>
          {error && <p className="field-error" role="alert">{error}</p>}
          <div className="button-row">
            <button type="submit" className="btn" disabled={saving || !dirty || !update.enabled}>{saving ? t("Saving…", "正在保存……") : t("Save notes", "保存备注")}</button>
            <button type="button" className="btn secondary" disabled={saving} onClick={cancelNotes}>{t("Cancel", "取消")}</button>
          </div>
        </form> : <p className="note-content">{plain(r.fields.notes) || t("No notes yet.", "还没有备注。")}</p>}
        {message && <p className="small muted" role="status">{message}</p>}
        <p className="small muted note-help">{t("Notes are saved with this recording in your account.", "备注将与这条记录一起保存在你的账号中。")}</p>
      </aside>
    </div>

    <Dialog open={metricInfo !== null} onOpenChange={open => { if (!open) setMetricInfo(null); }}>
      <DialogContent className="bm-app" lang={lang==="zh"?"zh-CN":"en"}><style>{CSS}</style>
        <DialogHeader><DialogTitle>{metricHelp.title}</DialogTitle><DialogDescription>{metricHelp.body}</DialogDescription></DialogHeader>
      </DialogContent>
    </Dialog>
  </>;
}
const READING_SOURCE_ORIGINS = new Set(["https://aasm.org", "https://archive.cdc.gov", "https://health.nih.gov", "https://medlineplus.gov", "https://oxfordhealth.nhs.uk", "https://pmc.ncbi.nlm.nih.gov", "https://womenshealth.gov", "https://www.cdc.gov", "https://www.fda.gov", "https://www.healthlinkbc.ca", "https://www.hopkinsmedicine.org", "https://www.hse.gov.uk", "https://www.mayoclinic.org", "https://www.medlineplus.gov", "https://www.nhlbi.nih.gov", "https://www.nhs.uk", "https://www.nhtsa.gov", "https://www.niaaa.nih.gov", "https://www.nichd.nih.gov", "https://www.nigms.nih.gov", "https://www.thensf.org"]);
// Reading routes retain the complete bilingual articles and their source links.
function ReadingLibrary({ lang, t, links }: any) {
  const language = lang === 'zh' ? 'zh' : 'en';
  const params = new URLSearchParams(typeof window !== 'undefined' ? window.location.search : '');
  const categoryId = params.get('category');
  const category = READING.categories.find((item: any) => item.id === categoryId) || READING.categories[0];
  const articleId = params.get('article');
  const article = READING.articles.find((item: any) => item.id === articleId);

  if (articleId && !article) return <div className="reading-library">
    <NavLink to={links.home} className="back-link"><ArrowLeft className="icon" />{t('Home', '个人首页')}</NavLink>
    <section className="empty-state">
      <h1>{t('This article could not be found', '没有找到这篇内容')}</h1>
      <p>{t('Return to the library to choose another article.', '这个链接暂时没有对应的文章，可以返回分类重新选择。')}</p>
      <NavLink to={withQuery(links.learn, { category: category.id, article: '' })} className="btn secondary">
        {t('Browse articles', '浏览文章')}<ArrowRight className="icon" />
      </NavLink>
    </section>
  </div>;

  if (article) {
    const currentCategory = READING.categories.find((item: any) => item.id === article.category);
    const categoryArticles = READING.articles.filter((item: any) => item.category === article.category);
    const articleIndex = categoryArticles.findIndex((item: any) => item.id === article.id);
    const next = categoryArticles[articleIndex + 1];
    // Keep the complete text, lists and tables. Source links are collected in
    // ArticleMeta rather than repeated after paragraphs throughout the body.
    const body = article.blocks.map((block: any) => {
      const { links: sourceLinks, ...content } = block;
      return content;
    });
    return <>
      <div className="article-topline">
        <NavLink to={withQuery(links.learn, { category: article.category, article: '' })} className="back-link">
          <ArrowLeft className="icon" />{t('Back to articles', '返回文章列表')}
        </NavLink>
        <NavLink to={links.home} className="text-button">{t('Home', '个人首页')}</NavLink>
      </div>
      <article className="reading-document" aria-labelledby="article-title" lang={language === 'zh' ? 'zh-CN' : 'en'}>
        <header className="article-heading">
          <p className="article-category">{currentCategory?.title[language]}</p>
          <h1 id="article-title">{article.title[language]}</h1>
        </header>
        <div className="article-body"><ArticleBlocks blocks={body} lang={language} /></div>
        <ArticleMeta article={article} lang={language} t={t} />
        {next && <section className="article-next">
          <p className="small muted">{t('Related article', '同类文章')}</p>
          <h2>{next.title[language]}</h2>
          <NavLink to={withQuery(links.learn, { article: next.id, category: next.category })} className="text-button">
            {t('Continue reading', '继续阅读')}<ArrowRight className="icon" />
          </NavLink>
        </section>}
      </article>
    </>;
  }

  const articles = READING.articles.filter((item: any) => item.category === category.id);
  return <div className="reading-library">
    <NavLink to={links.home} className="back-link"><ArrowLeft className="icon" />{t('Home', '个人首页')}</NavLink>
    <div className="page-heading reading-heading"><div><h1>{t('Sleep guide', '睡眠知识')}</h1><p className="small muted">{t('Explore sleep and breathing, with knowledge and practical advice for everyday life.', '了解睡眠与呼吸，找到适合日常参考的知识与建议。')}</p></div></div>
    <div className="reading-filter">
      <nav className="reading-nav" aria-label={t('Sleep article categories', '睡眠文章分类')}>
        {READING.categories.map((item: any) => <NavigationAction
          key={item.id}
          navigation={withQuery(links.learn, { category: item.id, article: '' })}
          aria-current={category.id === item.id ? 'page' : undefined}
        >
          {item.id === 'basics' ? <Moon className="icon" /> : <BookOpen className="icon" />}{item.title[language]}
        </NavigationAction>)}
      </nav>
    </div>
    <section className="reading-category" aria-label={t('Sleep articles', '睡眠文章')}>
      <div className="article-list">
        {articles.map((item: any) => {
          return <article className="article-entry" key={item.id}>
            <div>
              <h2>{item.title[language]}</h2>
              <p>{item.summary[language]}</p>
            </div>
            <NavLink to={withQuery(links.learn, { article: item.id, category: item.category })} className="text-button">
              {t('Read article', '阅读全文')}<ArrowRight className="icon" />
            </NavLink>
          </article>;
        })}
      </div>
    </section>
  </div>;
}

function ArticleMeta({ article, lang, t }: any) {
  const language = lang === 'zh' ? 'zh' : 'en';
  const safeUrl = (value: any) => {
    if (typeof value !== 'string') return '';
    try {
      const url = new URL(value);
      return READING_SOURCE_ORIGINS.has(url.origin) && !url.username && !url.password ? url.href : '';
    } catch { return ''; }
  };
  const editorial = article.contentKind === 'editorial';
  const sources = Array.isArray(article.sources) ? article.sources : [];
  const primary = sources.find((source: any) => source.role === 'primary');
  const primaryUrl = safeUrl(primary?.url);
  const sourceName = primary?.org === 'NHLBI'
    ? 'National Heart, Lung, and Blood Institute; National Institutes of Health; U.S. Department of Health and Human Services.'
    : primary?.org === 'CDC'
      ? 'Centers for Disease Control and Prevention (CDC); National Center for Chronic Disease Prevention and Health Promotion.'
      : primary?.org || '';
  const related: any[] = [];
  const seen = new Set<string>(primaryUrl ? [primaryUrl] : []);
  const candidates = [
    ...sources.filter((source: any) => source.role !== 'primary').map((source: any) => ({ label: source.label, url: source.url })),
    ...(Array.isArray(article.blocks) ? article.blocks : []).flatMap((block: any) =>
      (Array.isArray(block.links) ? block.links : []).map((link: any) => ({ label: link.text, url: link.url }))
    ),
  ];
  for (const source of candidates) {
    const url = safeUrl(source.url);
    if (!url || seen.has(url)) continue;
    seen.add(url);
    const label = typeof source.label === 'string' ? source.label : source.label?.[language];
    related.push({ url, label: label || url });
  }
  return <footer className="article-sources"><details className="source-links">
    <summary>{t('References', '参考资料')}</summary>
    <p>{editorial ? t('Content: BreathMap educational guide · English and Chinese', '内容类型：BreathMap 原创科普整理 · 中英双语') : t('Content: English source article · Chinese translation', '内容类型：英文原文 · 中文译文')}</p>
    {sourceName && <p>{t("Source: ","来源：")}{sourceName}</p>}
    {primary?.updated && <p>{t('Source updated: ', '原文更新：')}{primary.updated}</p>}
    {primaryUrl && <a className="text-button" href={primaryUrl} target="_blank" rel="noopener noreferrer">
      {t('View original source', '查看原始资料')} ↗
    </a>}
    {!editorial && <p>{t(
      'The original is freely available on the source website. Article text, lists and tables are retained. Images, site navigation and promotional page interfaces are not reproduced. Popup glossary definitions follow the body, and related links appear below.',
      '来源网站免费提供原文。此处保留文章正文、列表和表格；不转载图片、网站导航及页面推广界面。术语弹窗释义收录于正文后，相关链接列于下方。'
    )}</p>}
    {editorial ? <p>{t(`Written by BreathMap for general education, based on the references listed here. References checked: ${article.reviewed}. This article does not replace individual assessment by a healthcare professional.`, `BreathMap 根据所列资料编写，供一般知识学习；资料核对日期：${article.reviewed}。本文不能替代医疗专业人员的个体评估。`)}</p> : <p>{t(
      `Source checked and translated: ${article.reviewed || READING.reviewed}. The Chinese translation was prepared for BreathMap and has not been reviewed or approved by the source agencies. Use of this material does not imply endorsement of BreathMap by NHLBI, NIH, CDC, HHS or the U.S. Government.`,
      `资料核对与翻译日期：${article.reviewed || READING.reviewed}。翻译由 BreathMap 整理，未经来源机构审核或认可；引用不表示 NHLBI、NIH、CDC、HHS 或美国政府对 BreathMap 的认可或推荐。`
    )}</p>}
    {related.length > 0 && <ul>{related.map(source => <li key={source.url}>
        <a href={source.url} target="_blank" rel="noopener noreferrer">{source.label} ↗</a>
      </li>)}</ul>}
  </details></footer>;
}
// Renders the ordered bilingual blocks in reading.json without parsing source HTML.
function ArticleBlocks({ blocks, lang }: any) {
  const language = lang === 'zh' ? 'zh' : 'en';
  const sourceOrigins = READING_SOURCE_ORIGINS;
  const entries = Array.isArray(blocks) ? blocks : [];
  const text = (block: any) => typeof block?.[language] === 'string' ? block[language] : '';

  const references = (block: any) => {
    const seen = new Set<string>();
    const links: any[] = [];
    for (const link of Array.isArray(block?.links) ? block.links : []) {
      if (typeof link?.url !== 'string') continue;
      try {
        const url = new URL(link.url);
        if (!sourceOrigins.has(url.origin) || url.username || url.password || seen.has(url.href)) continue;
        seen.add(url.href);
        links.push({ href: url.href, label: typeof link.text === 'string' && link.text ? link.text : url.href });
      } catch { /* Ignore malformed or relative URLs; reading.json already resolves source links. */ }
    }
    if (!links.length) return null;
    return <span className="bm-article-references">{' '}
      ({language === 'zh' ? '相关资料：' : 'Related: '}
      {links.map((link, index) => <span key={link.href}>
        {index > 0 ? ' · ' : ''}<a href={link.href} target="_blank" rel="noopener noreferrer">{link.label}</a>
      </span>)}{')'}
    </span>;
  };

  const output: any[] = [];
  for (let index = 0; index < entries.length; index++) {
    const block = entries[index];
    if (!block || typeof block !== 'object') continue;

    if (block.type === 'li' || block.type === 'subli') {
      const start = index;
      const items: any[] = [];
      while (index < entries.length && ['li', 'subli'].includes(entries[index]?.type)) {
        const item = entries[index];
        const previous = items[items.length - 1];
        if (item.type === 'subli' && previous && !previous.orphan) {
          previous.children.push({ block: item, key: index });
        } else {
          // Orphan subli blocks become ordinary list items, never an invalid child of ul.
          items.push({ block: item, key: index, children: [], orphan: item.type === 'subli' });
        }
        index++;
      }
      index--;
      output.push(<ul key={`list-${start}`}>
        {items.map(item => <li key={item.key}>
          {text(item.block)}{references(item.block)}
          {item.children.length > 0 && <ul>{item.children.map((child: any) =>
            <li key={child.key}>{text(child.block)}{references(child.block)}</li>
          )}</ul>}
        </li>)}
      </ul>);
      continue;
    }

    if (block.type === 'table') {
      const headers = Array.isArray(block.headers?.[language]) ? block.headers[language] : [];
      const rows = Array.isArray(block.rows) ? block.rows : [];
      output.push(<div className="bm-table-wrap" key={`table-${index}`}>
        <table className="bm-table">
          <caption>{language === 'zh' ? '各年龄组建议睡眠时长' : 'Recommended sleep duration by age'}</caption>
          {headers.length > 0 && <thead><tr>{headers.map((cell: any, column: number) =>
            <th key={column} scope="col">{typeof cell === 'string' ? cell : ''}</th>
          )}</tr></thead>}
          <tbody>{rows.map((row: any, rowIndex: number) => <tr key={rowIndex}>
            {(Array.isArray(row?.[language]) ? row[language] : []).map((cell: any, column: number) =>
              <td key={column}>{typeof cell === 'string' ? cell : ''}</td>
            )}
          </tr>)}</tbody>
        </table>
      </div>);
      continue;
    }

    if (block.type === 'h2') output.push(<h2 key={index}>{text(block)}{references(block)}</h2>);
    else if (block.type === 'h3') output.push(<h3 key={index}>{text(block)}{references(block)}</h3>);
    else if (block.type === 'p') output.push(<p key={index}>{text(block)}{references(block)}</p>);
  }
  return <div className="bm-article-blocks" lang={language === 'zh' ? 'zh-CN' : 'en'}>{output}</div>;
}


function WellbeingPage(props:any){return null;}

function HomeOverview(props:any){return null;}
